window.KHO_DATA_L5_TIENGANH = [
{"lop":5,"mon":"Tiếng Anh","tuan":1,"tiet":1,"bai":"Starter — Làm quen SGK & ôn tập đầu năm (Tiếng Anh 5 Global Success)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Làm quen SGK Tiếng Anh 5 (Global Success), ôn kiến thức Tiếng Anh 4 (bảng chữ cái, số, chào hỏi cơ bản); tạo hứng thú, nội quy lớp học tiếng Anh.\n2. Năng lực chung: Tự chủ và tự học; Giao tiếp và hợp tác.\n3. Phẩm chất: Chăm chỉ, tự tin, trung thực trong kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được một từ trong từ điển điện tử, nghe phát âm, đọc ví dụ và ghi cách dùng vào sổ tay.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS chơi trò chơi/hỏi–đáp nhanh để huy động lại kiến thức đã học trong học kì.\n- Nêu mục tiêu tiết ôn tập, hệ thống các Unit trọng tâm chuẩn bị kiểm tra.","hs":"- HS tham gia, nhắc lại chủ đề – từ vựng; xác định nội dung cần ôn."},{"ten":"2. Nội dung chính","gv":"- GV tổ chức làm quen SGK Tiếng Anh 5 (Global Success), ôn kiến thức Tiếng Anh 4, giới thiệu chương trình và nội quy lớp học tiếng Anh.","hs":"- HS thực hiện nhiệm vụ theo hướng dẫn."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập/làm bài ôn, chữa và nhận xét.","hs":"- HS làm bài, tự đánh giá, rút kinh nghiệm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV giới thiệu bộ học liệu số của SGK Tiếng Anh 5 (Global Success): tệp audio từng Unit, mã QR trong sách, từ điển Anh – Việt điện tử có phát âm và có ví dụ; HS tự tra một từ đã học ở lớp 4, nghe phát âm, đọc phần ví dụ và ghi lại cách dùng vào sổ tay từ vựng.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV cho HS nghe cùng một câu tiếng Anh do người bản ngữ đọc trong audio SGK và do công cụ đọc tự động đọc; HS chỉ ra chỗ máy đọc chưa tự nhiên rồi cùng thống nhất nguyên tắc dùng công cụ số cả năm học: audio SGK là chuẩn để luyện nghe – nói, công cụ dịch và trợ lí trí tuệ nhân tạo chỉ để tra cứu, không dùng để làm hộ bài.\n⚠ (Miền 4: An toàn) Máy tính, loa của lớp là đồ dùng chung: mở đúng phần mềm và đúng trang GV cho phép, dùng xong đóng lại. Không nhập họ tên đầy đủ, ngày sinh, số điện thoại, ảnh cá nhân vào bất kì trang web hay ứng dụng học tiếng Anh nào; không bấm vào quảng cáo trong trang từ điển. Nghe bằng tai nghe thì mở nhỏ, mỗi lượt không quá 15 phút.","hs":"- HS tự tra được một từ trong từ điển điện tử, nghe phát âm, đọc ví dụ và ghi cách dùng vào sổ tay.\n- HS nêu được nguyên tắc dùng công cụ số trong môn Tiếng Anh: audio SGK để luyện nghe – nói, công cụ dịch chỉ để tra cứu."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":1,"tiet":2,"bai":"Unit 1 — Lesson 1 (All about me) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về giới thiệu bản thân, nơi ở.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: in Class 5A, live in the city, live in the countryside, tell me about yourself; mẫu câu: Can you tell me about yourself? – Yes. I'm in Class 5A. I live in the city.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được in Class 5A, live in the city, live in the countryside, tell me about yourself trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 1 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “All about me”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 1.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: in Class 5A, live in the city, live in the countryside, tell me about yourself.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Can you tell me about yourself? – Yes. I'm in Class 5A. I live in the city.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về giới thiệu bản thân, nơi ở).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 1 “All about me” cho HS nghe người bản ngữ đọc in Class 5A, live in the city, live in the countryside, tell me about yourself; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại in Class 5A, live in the city, live in the countryside, tell me about yourself vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được in Class 5A, live in the city, live in the countryside, tell me about yourself trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":1,"tiet":3,"bai":"Unit 1 — Lesson 1 (All about me) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về giới thiệu bản thân, nơi ở theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: in Class 5A, live in the city, live in the countryside, tell me about yourself; mẫu câu: Can you tell me about yourself? – Yes. I'm in Class 5A. I live in the city.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “All about me” (Unit 1) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 1.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"Can you tell me about yourself? – Yes. I'm in Class 5A. I live in the city.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":1,"tiet":4,"bai":"Unit 1 — Lesson 2 (All about me) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về lịch học, môn học ưa thích.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: study, subject, favourite; timetable; mẫu câu: What subjects do you have today? – I have Maths and English.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 1 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “All about me”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 1.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: study, subject, favourite; timetable.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"What subjects do you have today? – I have Maths and English.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về lịch học, môn học ưa thích.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":2,"tiet":1,"bai":"Unit 1 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Trọng âm / vần: /aɪ/ trong I, my; câu chant giới thiệu bản thân.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về lịch học, môn học ưa thích.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: study, subject, favourite; timetable; mẫu câu: What subjects do you have today? – I have Maths and English.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Trọng âm / vần: /aɪ/ trong I, my.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 1) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 1.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Trọng âm / vần: /aɪ/ trong I, my; câu chant giới thiệu bản thân..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"What subjects do you have today? – I have Maths and English.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về lịch học, môn học ưa thích.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 1 “All about me”: chiếu từ có gạch chân phần cần luyện (Trọng âm / vần: /aɪ/ trong I, my; câu chant giới thiệu bản thân), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Trọng âm / vần: /aɪ/ trong I, my; câu chant giới thiệu bản thân của Unit 1 “All about me” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":2,"tiet":2,"bai":"Unit 1 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về bản thân, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 1; mẫu câu: đọc đoạn giới thiệu bản thân; viết 2–3 câu về mình.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 1 “All about me”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 1 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 1.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về bản thân; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 1 “All about me”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về All about me để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 1 “All about me”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về All about me và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":2,"tiet":3,"bai":"Unit 1 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc đoạn giới thiệu bản thân; viết 2–3 câu về mình.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 1; mẫu câu: đọc đoạn giới thiệu bản thân; viết 2–3 câu về mình.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về All about me bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 1) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 1.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc đoạn giới thiệu bản thân; viết 2–3 câu về mình.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 1 “All about me”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về All about me; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 1 “All about me” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về All about me bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":2,"tiet":4,"bai":"Unit 2 — Lesson 1 (Our homes) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về các kiểu nhà, địa chỉ.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: flat, house, villa, town house; address; mẫu câu: What type of house do you live in? – I live in a flat.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được flat, house, villa, town house.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 2 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our homes”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 2.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: flat, house, villa, town house; address.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What type of house do you live in? – I live in a flat.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về các kiểu nhà, địa chỉ).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 2 “Our homes” cho HS nghe người bản ngữ đọc flat, house, villa, town house; address; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại flat, house, villa, town house; address vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được flat, house, villa, town house; address trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":3,"tiet":1,"bai":"Unit 2 — Lesson 1 (Our homes) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về các kiểu nhà, địa chỉ theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: flat, house, villa, town house; address; mẫu câu: What type of house do you live in? – I live in a flat.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Our homes” (Unit 2) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 2.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"What type of house do you live in? – I live in a flat.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":3,"tiet":2,"bai":"Unit 2 — Lesson 2 (Our homes) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về vị trí ngôi nhà.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: in the city centre, in the mountains, by the sea, in the countryside; mẫu câu: Where's your house? – It's in the mountains.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 2 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our homes”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 2.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: in the city centre, in the mountains, by the sea, in the countryside.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"Where's your house? – It's in the mountains.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về vị trí ngôi nhà.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":3,"tiet":3,"bai":"Unit 2 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /h/ trong house, home; chant về nhà ở.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về vị trí ngôi nhà.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: in the city centre, in the mountains, by the sea, in the countryside; mẫu câu: Where's your house? – It's in the mountains.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /h/ trong house, home.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 2) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 2.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /h/ trong house, home; chant về nhà ở..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"Where's your house? – It's in the mountains.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về vị trí ngôi nhà.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 2 “Our homes”: chiếu từ có gạch chân phần cần luyện (Âm /h/ trong house, home; chant về nhà ở), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /h/ trong house, home; chant về nhà ở của Unit 2 “Our homes” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":3,"tiet":4,"bai":"Unit 2 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về ngôi nhà, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 2; mẫu câu: đọc/viết mô tả ngôi nhà và nơi ở.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 2 “Our homes”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 2 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 2.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về ngôi nhà; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 2 “Our homes”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Our homes để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 2 “Our homes”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Our homes và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":4,"tiet":1,"bai":"Unit 2 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết mô tả ngôi nhà và nơi ở.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 2; mẫu câu: đọc/viết mô tả ngôi nhà và nơi ở.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Our homes bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 2) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 2.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết mô tả ngôi nhà và nơi ở.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 2 “Our homes”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Our homes; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 2 “Our homes” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Our homes bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":4,"tiet":2,"bai":"Unit 3 — Lesson 1 (My foreign friends) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về quốc tịch của bạn bè quốc tế.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: Vietnamese, Japanese, English, American, Australian; nationality; mẫu câu: Where's your friend from? – She's from Japan. She's Japanese.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được Vietnamese, Japanese, English, American, Australian.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 3 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “My foreign friends”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 3.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: Vietnamese, Japanese, English, American, Australian; nationality.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Where's your friend from? – She's from Japan. She's Japanese.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về quốc tịch của bạn bè quốc tế).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 3 “My foreign friends” cho HS nghe người bản ngữ đọc Vietnamese, Japanese, English, American, Australian; nationality; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại Vietnamese, Japanese, English, American, Australian; nationality vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được Vietnamese, Japanese, English, American, Australian; nationality trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":4,"tiet":3,"bai":"Unit 3 — Lesson 1 (My foreign friends) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về quốc tịch của bạn bè quốc tế theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: Vietnamese, Japanese, English, American, Australian; nationality; mẫu câu: Where's your friend from? – She's from Japan. She's Japanese.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “My foreign friends” (Unit 3) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 3.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"Where's your friend from? – She's from Japan. She's Japanese.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":4,"tiet":4,"bai":"Unit 3 — Lesson 2 (My foreign friends) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về ngôn ngữ, quốc gia.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: country, language; speak English/Japanese; mẫu câu: What nationality is he? – He's Australian. He speaks English.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 3 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “My foreign friends”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 3.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: country, language; speak English/Japanese.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"What nationality is he? – He's Australian. He speaks English.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về ngôn ngữ, quốc gia.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":5,"tiet":1,"bai":"Unit 3 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /ʃ/ trong nationality; chant về bạn bè quốc tế.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về ngôn ngữ, quốc gia.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: country, language; speak English/Japanese; mẫu câu: What nationality is he? – He's Australian. He speaks English.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /ʃ/ trong nationality.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 3) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 3.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /ʃ/ trong nationality; chant về bạn bè quốc tế..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"What nationality is he? – He's Australian. He speaks English.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về ngôn ngữ, quốc gia.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 3 “My foreign friends”: chiếu từ có gạch chân phần cần luyện (Âm /ʃ/ trong nationality; chant về bạn bè quốc tế), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /ʃ/ trong nationality; chant về bạn bè quốc tế của Unit 3 “My foreign friends” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":5,"tiet":2,"bai":"Unit 3 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về bạn nước ngoài, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 3; mẫu câu: đọc/viết giới thiệu một người bạn nước ngoài.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 3 “My foreign friends”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 3 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 3.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về bạn nước ngoài; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 3 “My foreign friends”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về My foreign friends để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 3 “My foreign friends”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về My foreign friends và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":5,"tiet":3,"bai":"Unit 3 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết giới thiệu một người bạn nước ngoài.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 3; mẫu câu: đọc/viết giới thiệu một người bạn nước ngoài.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về My foreign friends bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 3) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 3.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết giới thiệu một người bạn nước ngoài.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 3 “My foreign friends”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về My foreign friends; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 3 “My foreign friends” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về My foreign friends bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":5,"tiet":4,"bai":"Unit 4 — Lesson 1 (Our free-time activities) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về hoạt động lúc rảnh.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: go swimming, read comic books, watch TV, play games; free time; mẫu câu: What do you do in your free time? – I go swimming.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được go swimming, read comic books, watch TV, play games.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 4 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our free-time activities”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 4.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: go swimming, read comic books, watch TV, play games; free time.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What do you do in your free time? – I go swimming.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về hoạt động lúc rảnh).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 4 “Our free-time activities” cho HS nghe người bản ngữ đọc go swimming, read comic books, watch TV, play games; free time; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại go swimming, read comic books, watch TV, play games; free time vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được go swimming, read comic books, watch TV, play games; free time trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":6,"tiet":1,"bai":"Unit 4 — Lesson 1 (Our free-time activities) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về hoạt động lúc rảnh theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: go swimming, read comic books, watch TV, play games; free time; mẫu câu: What do you do in your free time? – I go swimming.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Our free-time activities” (Unit 4) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 4.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"What do you do in your free time? – I go swimming.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":6,"tiet":2,"bai":"Unit 4 — Lesson 2 (Our free-time activities) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về tần suất hoạt động.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: always, usually, often, sometimes; how often; mẫu câu: How often do you read books? – I sometimes read books.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 4 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our free-time activities”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 4.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: always, usually, often, sometimes; how often.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"How often do you read books? – I sometimes read books.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về tần suất hoạt động.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":6,"tiet":3,"bai":"Unit 4 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /iː/ trong free, read; chant về giờ rảnh.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về tần suất hoạt động.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: always, usually, often, sometimes; how often; mẫu câu: How often do you read books? – I sometimes read books.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /iː/ trong free, read.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 4) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 4.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /iː/ trong free, read; chant về giờ rảnh..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"How often do you read books? – I sometimes read books.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về tần suất hoạt động.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 4 “Our free-time activities”: chiếu từ có gạch chân phần cần luyện (Âm /iː/ trong free, read; chant về giờ rảnh), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /iː/ trong free, read; chant về giờ rảnh của Unit 4 “Our free-time activities” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":6,"tiet":4,"bai":"Unit 4 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về giờ rảnh, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 4; mẫu câu: đọc/viết về hoạt động lúc rảnh của em.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 4 “Our free-time activities”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 4 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 4.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về giờ rảnh; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 4 “Our free-time activities”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Our free-time activities để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 4 “Our free-time activities”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Our free-time activities và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":7,"tiet":1,"bai":"Unit 4 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết về hoạt động lúc rảnh của em.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 4; mẫu câu: đọc/viết về hoạt động lúc rảnh của em.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Our free-time activities bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 4) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 4.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết về hoạt động lúc rảnh của em.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 4 “Our free-time activities”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Our free-time activities; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 4 “Our free-time activities” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Our free-time activities bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":7,"tiet":2,"bai":"Unit 5 — Lesson 1 (My future job) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về nghề nghiệp mơ ước.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: doctor, teacher, pilot, engineer, farmer; future job; mẫu câu: What do you want to be in the future? – I want to be a doctor.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được doctor, teacher, pilot, engineer, farmer.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 5 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “My future job”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 5.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: doctor, teacher, pilot, engineer, farmer; future job.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What do you want to be in the future? – I want to be a doctor.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về nghề nghiệp mơ ước).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 5 “My future job” cho HS nghe người bản ngữ đọc doctor, teacher, pilot, engineer, farmer; future job; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại doctor, teacher, pilot, engineer, farmer; future job vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được doctor, teacher, pilot, engineer, farmer; future job trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":7,"tiet":3,"bai":"Unit 5 — Lesson 1 (My future job) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về nghề nghiệp mơ ước theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: doctor, teacher, pilot, engineer, farmer; future job; mẫu câu: What do you want to be in the future? – I want to be a doctor.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “My future job” (Unit 5) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 5.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"What do you want to be in the future? – I want to be a doctor.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":7,"tiet":4,"bai":"Unit 5 — Lesson 2 (My future job) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về lí do chọn nghề.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: because; help people, fly a plane, grow food; mẫu câu: Why do you want to be a pilot? – Because I want to fly a plane.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 5 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “My future job”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 5.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: because; help people, fly a plane, grow food.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"Why do you want to be a pilot? – Because I want to fly a plane.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về lí do chọn nghề.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":8,"tiet":1,"bai":"Unit 5 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /dʒ/ trong job, engineer; chant về nghề nghiệp.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về lí do chọn nghề.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: because; help people, fly a plane, grow food; mẫu câu: Why do you want to be a pilot? – Because I want to fly a plane.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /dʒ/ trong job, engineer.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 5) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 5.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /dʒ/ trong job, engineer; chant về nghề nghiệp..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"Why do you want to be a pilot? – Because I want to fly a plane.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về lí do chọn nghề.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 5 “My future job”: chiếu từ có gạch chân phần cần luyện (Âm /dʒ/ trong job, engineer; chant về nghề nghiệp), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /dʒ/ trong job, engineer; chant về nghề nghiệp của Unit 5 “My future job” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":8,"tiet":2,"bai":"Unit 5 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về nghề tương lai, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 5; mẫu câu: đọc/viết về nghề em mơ ước và lí do.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 5 “My future job”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 5 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 5.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về nghề tương lai; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 5 “My future job”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về My future job để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 5 “My future job”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về My future job và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":8,"tiet":3,"bai":"Unit 5 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết về nghề em mơ ước và lí do.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 5; mẫu câu: đọc/viết về nghề em mơ ước và lí do.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về My future job bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 5) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 5.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết về nghề em mơ ước và lí do.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 5 “My future job”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về My future job; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 5 “My future job” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về My future job bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":8,"tiet":4,"bai":"Review 1 (Ôn tập – Nghe – Đọc)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá và củng cố ngữ liệu (từ vựng, mẫu câu) qua kĩ năng Nghe – Đọc của các Unit đã học.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề và sáng tạo.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực trong ôn tập và kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS làm được bài ôn tương tác của “Review 1 (Ôn tập – Nghe – Đọc)”, tự xác định ba phần còn yếu trong Unit 1–5 và chọn bài luyện tiếp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 1–5.\n- Nêu mục tiêu Review 1: củng cố kĩ năng Nghe và Đọc.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 1–5.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn tập theo kĩ năng","gv":"- GV tổ chức ôn Nghe – Đọc qua hệ thống bài tập (Listen/Read/Speak/Write) trong phần Review.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập theo cặp/nhóm, vận dụng ngữ liệu tổng hợp.","hs":"- HS thực hành, sửa lỗi cho nhau."},{"ten":"4. Fun time / Củng cố","gv":"- GV tổ chức trò chơi/hoạt động Fun time; tổng kết kiến thức trọng tâm.","hs":"- HS tham gia, hệ thống lại ngữ liệu đã ôn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) GV giao bộ bài tập tương tác có chấm tự động cho “Review 1 (Ôn tập – Nghe – Đọc)” với ngữ liệu Unit 1–5: nghe chọn đáp án, đọc đoạn rồi trả lời câu hỏi, sắp lại trật tự câu. HS tự làm, đọc kết quả từng câu, ghi ra ba phần mình sai nhiều nhất rồi chọn tiếp bài luyện đúng phần đó.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tự tra lại trong từ điển điện tử những từ của Unit 1–5 còn quên, đọc cả nghĩa lẫn ví dụ để chọn nghĩa hợp ngữ cảnh, nghe phát âm rồi sắp xếp bổ sung vào sổ tay từ vựng theo nhóm chủ đề để dễ ôn.\n⚠ (Miền 4: An toàn) Tự làm hết bài rồi mới xem đáp án; kết quả máy chấm là để biết mình hổng chỗ nào, không phải để so điểm với bạn. Chỉ mở đúng đường dẫn GV gửi, không mở sang mạng xã hội hay trò chơi trong giờ ôn. Không đăng nhập bằng tài khoản của bạn và không gõ họ tên đầy đủ, ngày sinh khi phần mềm hỏi.","hs":"- HS làm được bài ôn tương tác của “Review 1 (Ôn tập – Nghe – Đọc)”, tự xác định ba phần còn yếu trong Unit 1–5 và chọn bài luyện tiếp.\n- HS tra và sắp xếp bổ sung được từ còn quên vào sổ tay từ vựng theo nhóm chủ đề."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":9,"tiet":1,"bai":"Review 1 (Ôn tập – Nói – Viết)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá và củng cố ngữ liệu (từ vựng, mẫu câu) qua kĩ năng Nói – Viết của các Unit đã học.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề và sáng tạo.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực trong ôn tập và kiểm tra – đánh giá.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 1–5.\n- Nêu mục tiêu Review 1: củng cố kĩ năng Nói và Viết.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 1–5.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn tập theo kĩ năng","gv":"- GV tổ chức ôn Nói – Viết qua hệ thống bài tập (Listen/Read/Speak/Write) trong phần Review.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập theo cặp/nhóm, vận dụng ngữ liệu tổng hợp.","hs":"- HS thực hành, sửa lỗi cho nhau."},{"ten":"4. Fun time / Củng cố","gv":"- GV tổ chức trò chơi/hoạt động Fun time; tổng kết kiến thức trọng tâm.","hs":"- HS tham gia, hệ thống lại ngữ liệu đã ôn."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":9,"tiet":2,"bai":"Review 1 (Fun time & Củng cố)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá và củng cố ngữ liệu (từ vựng, mẫu câu) qua kĩ năng tổng hợp của các Unit đã học.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề và sáng tạo.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực trong ôn tập và kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS tham gia bộ câu hỏi tương tác ôn Unit 1–5 trong “Review 1 (Fun time & Củng cố)” và chỉ ra được nhóm từ mình còn quên nhiều nhất.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 1–5.\n- Nêu mục tiêu Review 1: củng cố trò chơi ngôn ngữ, hệ thống hoá từ vựng – mẫu câu.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 1–5.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn tập theo kĩ năng","gv":"- GV tổ chức ôn tổng hợp qua hệ thống bài tập (Listen/Read/Speak/Write) trong phần Review.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập theo cặp/nhóm, vận dụng ngữ liệu tổng hợp.","hs":"- HS thực hành, sửa lỗi cho nhau."},{"ten":"4. Fun time / Củng cố","gv":"- GV tổ chức trò chơi/hoạt động Fun time; tổng kết kiến thức trọng tâm.","hs":"- HS tham gia, hệ thống lại ngữ liệu đã ôn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) GV tổ chức phần Fun time của “Review 1 (Fun time & Củng cố)” bằng bộ câu hỏi tương tác chấm tự động cho ngữ liệu Unit 1–5: nghe đoán từ, ghép câu, đoán chữ; HS chơi theo nhóm, nhìn bảng điểm hiện ngay trên màn hình và tự chỉ ra nhóm từ nào cả nhóm còn quên nhiều nhất.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ một câu ôn tập của Unit 1–5 vào công cụ dịch tự động rồi dịch ngược lại tiếng Việt, chiếu cả hai chiều cho HS thấy nghĩa đã lệch đi thế nào; HS giải thích vì sao không nên tin ngay câu máy dịch mà phải đối chiếu với mẫu câu đã học trong SGK.\n⚠ (Miền 4: An toàn) Chơi theo nhóm thì thắng thua vui vẻ, không chê bạn trả lời sai; bảng điểm là để biết nhóm mình cần ôn gì, không phải để xếp hạng bạn nào giỏi bạn nào kém. Chỉ mở đúng đường dẫn trò chơi GV gửi, không mở sang trang khác; phần mềm hỏi tên thì dùng tên nhóm, không gõ họ tên đầy đủ của HS.","hs":"- HS tham gia bộ câu hỏi tương tác ôn Unit 1–5 trong “Review 1 (Fun time & Củng cố)” và chỉ ra được nhóm từ mình còn quên nhiều nhất.\n- HS giải thích được vì sao phải đối chiếu câu do công cụ dịch đưa ra với mẫu câu trong SGK."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":9,"tiet":3,"bai":"Unit 6 — Lesson 1 (Our school rooms) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về các phòng trong trường.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: library, computer room, art room, music room, gym; mẫu câu: Where's the library? – It's on the first floor.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được library, computer room, art room, music room, gym trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 6 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our school rooms”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 6.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: library, computer room, art room, music room, gym.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Where's the library? – It's on the first floor.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về các phòng trong trường).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 6 “Our school rooms” cho HS nghe người bản ngữ đọc library, computer room, art room, music room, gym; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại library, computer room, art room, music room, gym vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được library, computer room, art room, music room, gym trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":9,"tiet":4,"bai":"Unit 6 — Lesson 1 (Our school rooms) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về các phòng trong trường theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: library, computer room, art room, music room, gym; mẫu câu: Where's the library? – It's on the first floor.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Our school rooms” (Unit 6) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 6.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"Where's the library? – It's on the first floor.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":10,"tiet":1,"bai":"Unit 6 — Lesson 2 (Our school rooms) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về hoạt động ở từng phòng.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: read books, use computers, draw pictures, sing songs; mẫu câu: What do you do in the art room? – I draw pictures.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 6 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our school rooms”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 6.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: read books, use computers, draw pictures, sing songs.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"What do you do in the art room? – I draw pictures.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về hoạt động ở từng phòng.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":10,"tiet":2,"bai":"Unit 6 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /uː/ trong room, school; chant về phòng học.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về hoạt động ở từng phòng.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: read books, use computers, draw pictures, sing songs; mẫu câu: What do you do in the art room? – I draw pictures.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /uː/ trong room, school.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 6) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 6.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /uː/ trong room, school; chant về phòng học..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"What do you do in the art room? – I draw pictures.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về hoạt động ở từng phòng.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 6 “Our school rooms”: chiếu từ có gạch chân phần cần luyện (Âm /uː/ trong room, school; chant về phòng học), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /uː/ trong room, school; chant về phòng học của Unit 6 “Our school rooms” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":10,"tiet":3,"bai":"Unit 6 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về phòng trong trường, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 6; mẫu câu: đọc/viết mô tả các phòng ở trường.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 6 “Our school rooms”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 6 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 6.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về phòng trong trường; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 6 “Our school rooms”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Our school rooms để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 6 “Our school rooms”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Our school rooms và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":10,"tiet":4,"bai":"Unit 6 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết mô tả các phòng ở trường.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 6; mẫu câu: đọc/viết mô tả các phòng ở trường.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Our school rooms bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 6) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 6.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết mô tả các phòng ở trường.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 6 “Our school rooms”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Our school rooms; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 6 “Our school rooms” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Our school rooms bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":11,"tiet":1,"bai":"Unit 7 — Lesson 1 (Our favourite school activities) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về hoạt động ở trường.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: have English lessons, do sports, do experiments, plant trees; mẫu câu: What's your favourite school activity? – It's doing experiments.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được have English lessons, do sports, do experiments, plant trees trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 7 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our favourite school activities”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 7.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: have English lessons, do sports, do experiments, plant trees.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What's your favourite school activity? – It's doing experiments.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về hoạt động ở trường).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 7 “Our favourite school activities” cho HS nghe người bản ngữ đọc have English lessons, do sports, do experiments, plant trees; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại have English lessons, do sports, do experiments, plant trees vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được have English lessons, do sports, do experiments, plant trees trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":11,"tiet":2,"bai":"Unit 7 — Lesson 1 (Our favourite school activities) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về hoạt động ở trường theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: have English lessons, do sports, do experiments, plant trees; mẫu câu: What's your favourite school activity? – It's doing experiments.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Our favourite school activities” (Unit 7) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 7.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"What's your favourite school activity? – It's doing experiments.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":11,"tiet":3,"bai":"Unit 7 — Lesson 2 (Our favourite school activities) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về lịch hoạt động trong tuần.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: days of the week; on Monday, twice a week; mẫu câu: When do you have Music? – I have Music on Tuesday.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 7 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our favourite school activities”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 7.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: days of the week; on Monday, twice a week.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"When do you have Music? – I have Music on Tuesday.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về lịch hoạt động trong tuần.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":11,"tiet":4,"bai":"Unit 7 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /v/ trong favourite, activity; chant về hoạt động.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về lịch hoạt động trong tuần.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: days of the week; on Monday, twice a week; mẫu câu: When do you have Music? – I have Music on Tuesday.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /v/ trong favourite, activity.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 7) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 7.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /v/ trong favourite, activity; chant về hoạt động..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"When do you have Music? – I have Music on Tuesday.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về lịch hoạt động trong tuần.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 7 “Our favourite school activities”: chiếu từ có gạch chân phần cần luyện (Âm /v/ trong favourite, activity; chant về hoạt động), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /v/ trong favourite, activity; chant về hoạt động của Unit 7 “Our favourite school activities” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":12,"tiet":1,"bai":"Unit 7 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về hoạt động ở trường, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 7; mẫu câu: đọc/viết về hoạt động em thích ở trường.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 7 “Our favourite school activities”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 7 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 7.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về hoạt động ở trường; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 7 “Our favourite school activities”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Our favourite school activities để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 7 “Our favourite school activities”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Our favourite school activities và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":12,"tiet":2,"bai":"Unit 7 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết về hoạt động em thích ở trường.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 7; mẫu câu: đọc/viết về hoạt động em thích ở trường.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Our favourite school activities bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 7) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 7.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết về hoạt động em thích ở trường.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 7 “Our favourite school activities”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Our favourite school activities; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 7 “Our favourite school activities” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Our favourite school activities bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":12,"tiet":3,"bai":"Kiểm tra định kì giữa học kì I","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Đánh giá kết quả giữa học kì I qua bốn kĩ năng Nghe – Đọc – Nói – Viết theo ma trận đề phù hợp chuẩn đầu ra Tiếng Anh 5.\n2. Năng lực chung:\n- Tự chủ và tự học; Giải quyết vấn đề.\n3. Phẩm chất:\n- Trung thực, tự giác, nghiêm túc trong kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 6.1 CB2 (Hiểu biết về trí tuệ nhân tạo): HS thực hiện đúng quy định không dùng thiết bị số trong giờ kiểm tra, làm bài bằng năng lực của chính mình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Ổn định – Phổ biến","gv":"- GV ổn định lớp, tạo tâm lí thoải mái, tự tin trước khi làm bài.\n- Nhắc hình thức, thời gian và quy tắc làm bài kiểm tra; phát đề.","hs":"- HS chuẩn bị đồ dùng, giữ trật tự, lắng nghe hướng dẫn làm bài."},{"ten":"2. Làm bài / Thực hiện","gv":"- GV phát đề/tổ chức kiểm tra bốn kĩ năng; coi kiểm tra nghiêm túc.","hs":"- HS làm bài độc lập, trung thực."},{"ten":"3. Thu bài – Nhận xét","gv":"- GV thu bài, nhận xét chung tinh thần, thái độ làm bài.","hs":"- HS nộp bài, rút kinh nghiệm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) Tiết kiểm tra là dịp dạy chính về liêm chính học tập: GV nêu rõ công cụ dịch tự động và trợ lí trí tuệ nhân tạo có thể làm hộ cả bài nghe, đọc, viết, nhưng bài kiểm tra là để đo năng lực thật của chính HS; vì vậy trong giờ kiểm tra tuyệt đối không dùng thiết bị số.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Sau khi trả bài, GV hướng dẫn HS dùng từ điển Anh – Việt điện tử tra lại đúng những từ mình làm sai, nghe phát âm chuẩn và ghi vào sổ tay từ vựng của riêng mình.\n⚠ (Miền 4: An toàn) Không mang và không sử dụng thiết bị số trong giờ kiểm tra; không chụp đề bài gửi lên nhóm chat hay ứng dụng nào; không nhờ người khác làm hộ qua mạng.","hs":"- HS thực hiện đúng quy định không dùng thiết bị số trong giờ kiểm tra, làm bài bằng năng lực của chính mình.\n- HS nêu được vì sao nhờ công cụ dịch hay trợ lí AI làm hộ bài kiểm tra là không trung thực; sau khi trả bài mới dùng từ điển điện tử để học lại từ chưa biết."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":12,"tiet":4,"bai":"Unit 8 — Lesson 1 (In our classroom) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về đồ vật, mệnh lệnh trong lớp.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: board, poster, cupboard, notice board; open, close, clean; mẫu câu: What are you doing? – I'm cleaning the board.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được board, poster, cupboard, notice board.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 8 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “In our classroom”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 8.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: board, poster, cupboard, notice board; open, close, clean.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What are you doing? – I'm cleaning the board.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về đồ vật, mệnh lệnh trong lớp).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 8 “In our classroom” cho HS nghe người bản ngữ đọc board, poster, cupboard, notice board; open, close, clean; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại board, poster, cupboard, notice board; open, close, clean vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được board, poster, cupboard, notice board; open, close, clean trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":13,"tiet":1,"bai":"Unit 8 — Lesson 1 (In our classroom) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về đồ vật, mệnh lệnh trong lớp theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: board, poster, cupboard, notice board; open, close, clean; mẫu câu: What are you doing? – I'm cleaning the board.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “In our classroom” (Unit 8) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 8.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"What are you doing? – I'm cleaning the board.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":13,"tiet":2,"bai":"Unit 8 — Lesson 2 (In our classroom) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về nội quy lớp học.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: be quiet, don't run, put up your hand; classroom rules; mẫu câu: What are the class rules? – Be quiet in class. Don't run.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 8 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “In our classroom”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 8.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: be quiet, don't run, put up your hand; classroom rules.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"What are the class rules? – Be quiet in class. Don't run.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về nội quy lớp học.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":13,"tiet":3,"bai":"Unit 8 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /kl/ trong class, clean; chant nội quy lớp.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về nội quy lớp học.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: be quiet, don't run, put up your hand; classroom rules; mẫu câu: What are the class rules? – Be quiet in class. Don't run.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /kl/ trong class, clean.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 8) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 8.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /kl/ trong class, clean; chant nội quy lớp..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"What are the class rules? – Be quiet in class. Don't run.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về nội quy lớp học.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 8 “In our classroom”: chiếu từ có gạch chân phần cần luyện (Âm /kl/ trong class, clean; chant nội quy lớp), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /kl/ trong class, clean; chant nội quy lớp của Unit 8 “In our classroom” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":13,"tiet":4,"bai":"Unit 8 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về lớp học, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 8; mẫu câu: đọc/viết về đồ vật và nội quy lớp học.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 8 “In our classroom”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 8 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 8.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về lớp học; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 8 “In our classroom”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về In our classroom để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 8 “In our classroom”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về In our classroom và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":14,"tiet":1,"bai":"Unit 8 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết về đồ vật và nội quy lớp học.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 8; mẫu câu: đọc/viết về đồ vật và nội quy lớp học.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về In our classroom bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 8) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 8.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết về đồ vật và nội quy lớp học.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 8 “In our classroom”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về In our classroom; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 8 “In our classroom” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về In our classroom bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":14,"tiet":2,"bai":"Unit 9 — Lesson 1 (Our outdoor activities) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về hoạt động ngoài trời.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: fly a kite, ride a bike, go camping, have a picnic; mẫu câu: What do you like doing outdoors? – I like flying a kite.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được fly a kite, ride a bike, go camping, have a picnic trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 9 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our outdoor activities”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 9.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: fly a kite, ride a bike, go camping, have a picnic.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What do you like doing outdoors? – I like flying a kite.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về hoạt động ngoài trời).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 9 “Our outdoor activities” cho HS nghe người bản ngữ đọc fly a kite, ride a bike, go camping, have a picnic; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại fly a kite, ride a bike, go camping, have a picnic vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được fly a kite, ride a bike, go camping, have a picnic trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":14,"tiet":3,"bai":"Unit 9 — Lesson 1 (Our outdoor activities) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về hoạt động ngoài trời theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: fly a kite, ride a bike, go camping, have a picnic; mẫu câu: What do you like doing outdoors? – I like flying a kite.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Our outdoor activities” (Unit 9) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 9.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"What do you like doing outdoors? – I like flying a kite.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":14,"tiet":4,"bai":"Unit 9 — Lesson 2 (Our outdoor activities) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về kế hoạch cuối tuần.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: this weekend; going to; mẫu câu: What are you going to do this weekend? – I'm going to go camping.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 9 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our outdoor activities”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 9.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: this weekend; going to.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"What are you going to do this weekend? – I'm going to go camping.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về kế hoạch cuối tuần.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":15,"tiet":1,"bai":"Unit 9 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /aʊ/ trong outdoor, mountain; chant hoạt động ngoài trời.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về kế hoạch cuối tuần.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: this weekend; going to; mẫu câu: What are you going to do this weekend? – I'm going to go camping.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /aʊ/ trong outdoor, mountain.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 9) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 9.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /aʊ/ trong outdoor, mountain; chant hoạt động ngoài trời..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"What are you going to do this weekend? – I'm going to go camping.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về kế hoạch cuối tuần.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 9 “Our outdoor activities”: chiếu từ có gạch chân phần cần luyện (Âm /aʊ/ trong outdoor, mountain; chant hoạt động ngoài trời), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /aʊ/ trong outdoor, mountain; chant hoạt động ngoài trời của Unit 9 “Our outdoor activities” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":15,"tiet":2,"bai":"Unit 9 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về hoạt động ngoài trời, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 9; mẫu câu: đọc/viết về hoạt động ngoài trời em yêu thích.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 9 “Our outdoor activities”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 9 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 9.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về hoạt động ngoài trời; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 9 “Our outdoor activities”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Our outdoor activities để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 9 “Our outdoor activities”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Our outdoor activities và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":15,"tiet":3,"bai":"Unit 9 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết về hoạt động ngoài trời em yêu thích.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 9; mẫu câu: đọc/viết về hoạt động ngoài trời em yêu thích.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Our outdoor activities bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 9) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 9.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết về hoạt động ngoài trời em yêu thích.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 9 “Our outdoor activities”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Our outdoor activities; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 9 “Our outdoor activities” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Our outdoor activities bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":15,"tiet":4,"bai":"Unit 10 — Lesson 1 (Our school trip) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về chuyến đi dã ngoại của trường.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: school trip, zoo, museum, farm, botanical garden; mẫu câu: Where did you go on your school trip? – I went to the zoo.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được school trip, zoo, museum, farm, botanical garden trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 10 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our school trip”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 10.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: school trip, zoo, museum, farm, botanical garden.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Where did you go on your school trip? – I went to the zoo.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về chuyến đi dã ngoại của trường).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 10 “Our school trip” cho HS nghe người bản ngữ đọc school trip, zoo, museum, farm, botanical garden; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại school trip, zoo, museum, farm, botanical garden vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được school trip, zoo, museum, farm, botanical garden trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":16,"tiet":1,"bai":"Unit 10 — Lesson 1 (Our school trip) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về chuyến đi dã ngoại của trường theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: school trip, zoo, museum, farm, botanical garden; mẫu câu: Where did you go on your school trip? – I went to the zoo.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Our school trip” (Unit 10) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 10.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"Where did you go on your school trip? – I went to the zoo.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":16,"tiet":2,"bai":"Unit 10 — Lesson 2 (Our school trip) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về hoạt động trong chuyến đi.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: saw animals, took photos, had fun; past simple; mẫu câu: What did you do there? – I saw many animals and took photos.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 10 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our school trip”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 10.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: saw animals, took photos, had fun; past simple.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"What did you do there? – I saw many animals and took photos.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về hoạt động trong chuyến đi.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":16,"tiet":3,"bai":"Unit 10 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /t/ /d/ /ɪd/ cuối động từ quá khứ; chant về chuyến đi.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về hoạt động trong chuyến đi.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: saw animals, took photos, had fun; past simple; mẫu câu: What did you do there? – I saw many animals and took photos.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /t/ /d/ /ɪd/ cuối động từ quá khứ.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 10) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 10.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /t/ /d/ /ɪd/ cuối động từ quá khứ; chant về chuyến đi..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"What did you do there? – I saw many animals and took photos.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về hoạt động trong chuyến đi.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 10 “Our school trip”: chiếu từ có gạch chân phần cần luyện (Âm /t/ /d/ /ɪd/ cuối động từ quá khứ; chant về chuyến đi), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /t/ /d/ /ɪd/ cuối động từ quá khứ; chant về chuyến đi của Unit 10 “Our school trip” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":16,"tiet":4,"bai":"Unit 10 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về chuyến đi trường, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 10; mẫu câu: đọc/viết kể lại một chuyến đi của trường.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 10 “Our school trip”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 10 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 10.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về chuyến đi trường; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 10 “Our school trip”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Our school trip để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 10 “Our school trip”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Our school trip và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":17,"tiet":1,"bai":"Unit 10 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết kể lại một chuyến đi của trường.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 10; mẫu câu: đọc/viết kể lại một chuyến đi của trường.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Our school trip bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 10) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 10.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết kể lại một chuyến đi của trường.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 10 “Our school trip”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Our school trip; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 10 “Our school trip” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Our school trip bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":17,"tiet":2,"bai":"Review 2 (Ôn tập – Nghe – Đọc)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá và củng cố ngữ liệu (từ vựng, mẫu câu) qua kĩ năng Nghe – Đọc của các Unit đã học.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề và sáng tạo.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực trong ôn tập và kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS làm được bài ôn tương tác của “Review 2 (Ôn tập – Nghe – Đọc)”, tự xác định ba phần còn yếu trong Unit 6–10 và chọn bài luyện tiếp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 6–10.\n- Nêu mục tiêu Review 2: củng cố kĩ năng Nghe và Đọc.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 6–10.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn tập theo kĩ năng","gv":"- GV tổ chức ôn Nghe – Đọc qua hệ thống bài tập (Listen/Read/Speak/Write) trong phần Review.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập theo cặp/nhóm, vận dụng ngữ liệu tổng hợp.","hs":"- HS thực hành, sửa lỗi cho nhau."},{"ten":"4. Fun time / Củng cố","gv":"- GV tổ chức trò chơi/hoạt động Fun time; tổng kết kiến thức trọng tâm.","hs":"- HS tham gia, hệ thống lại ngữ liệu đã ôn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) GV giao bộ bài tập tương tác có chấm tự động cho “Review 2 (Ôn tập – Nghe – Đọc)” với ngữ liệu Unit 6–10: nghe chọn đáp án, đọc đoạn rồi trả lời câu hỏi, sắp lại trật tự câu. HS tự làm, đọc kết quả từng câu, ghi ra ba phần mình sai nhiều nhất rồi chọn tiếp bài luyện đúng phần đó.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tự tra lại trong từ điển điện tử những từ của Unit 6–10 còn quên, đọc cả nghĩa lẫn ví dụ để chọn nghĩa hợp ngữ cảnh, nghe phát âm rồi sắp xếp bổ sung vào sổ tay từ vựng theo nhóm chủ đề để dễ ôn.\n⚠ (Miền 4: An toàn) Tự làm hết bài rồi mới xem đáp án; kết quả máy chấm là để biết mình hổng chỗ nào, không phải để so điểm với bạn. Chỉ mở đúng đường dẫn GV gửi, không mở sang mạng xã hội hay trò chơi trong giờ ôn. Không đăng nhập bằng tài khoản của bạn và không gõ họ tên đầy đủ, ngày sinh khi phần mềm hỏi.","hs":"- HS làm được bài ôn tương tác của “Review 2 (Ôn tập – Nghe – Đọc)”, tự xác định ba phần còn yếu trong Unit 6–10 và chọn bài luyện tiếp.\n- HS tra và sắp xếp bổ sung được từ còn quên vào sổ tay từ vựng theo nhóm chủ đề."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":17,"tiet":3,"bai":"Review 2 (Ôn tập – Nói – Viết)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá và củng cố ngữ liệu (từ vựng, mẫu câu) qua kĩ năng Nói – Viết của các Unit đã học.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề và sáng tạo.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực trong ôn tập và kiểm tra – đánh giá.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 6–10.\n- Nêu mục tiêu Review 2: củng cố kĩ năng Nói và Viết.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 6–10.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn tập theo kĩ năng","gv":"- GV tổ chức ôn Nói – Viết qua hệ thống bài tập (Listen/Read/Speak/Write) trong phần Review.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập theo cặp/nhóm, vận dụng ngữ liệu tổng hợp.","hs":"- HS thực hành, sửa lỗi cho nhau."},{"ten":"4. Fun time / Củng cố","gv":"- GV tổ chức trò chơi/hoạt động Fun time; tổng kết kiến thức trọng tâm.","hs":"- HS tham gia, hệ thống lại ngữ liệu đã ôn."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":17,"tiet":4,"bai":"Review 2 (Fun time & Củng cố)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá và củng cố ngữ liệu (từ vựng, mẫu câu) qua kĩ năng tổng hợp của các Unit đã học.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề và sáng tạo.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực trong ôn tập và kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS tham gia bộ câu hỏi tương tác ôn Unit 6–10 trong “Review 2 (Fun time & Củng cố)” và chỉ ra được nhóm từ mình còn quên nhiều nhất.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 6–10.\n- Nêu mục tiêu Review 2: củng cố trò chơi ngôn ngữ, hệ thống hoá từ vựng – mẫu câu.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 6–10.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn tập theo kĩ năng","gv":"- GV tổ chức ôn tổng hợp qua hệ thống bài tập (Listen/Read/Speak/Write) trong phần Review.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập theo cặp/nhóm, vận dụng ngữ liệu tổng hợp.","hs":"- HS thực hành, sửa lỗi cho nhau."},{"ten":"4. Fun time / Củng cố","gv":"- GV tổ chức trò chơi/hoạt động Fun time; tổng kết kiến thức trọng tâm.","hs":"- HS tham gia, hệ thống lại ngữ liệu đã ôn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) GV tổ chức phần Fun time của “Review 2 (Fun time & Củng cố)” bằng bộ câu hỏi tương tác chấm tự động cho ngữ liệu Unit 6–10: nghe đoán từ, ghép câu, đoán chữ; HS chơi theo nhóm, nhìn bảng điểm hiện ngay trên màn hình và tự chỉ ra nhóm từ nào cả nhóm còn quên nhiều nhất.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ một câu ôn tập của Unit 6–10 vào công cụ dịch tự động rồi dịch ngược lại tiếng Việt, chiếu cả hai chiều cho HS thấy nghĩa đã lệch đi thế nào; HS giải thích vì sao không nên tin ngay câu máy dịch mà phải đối chiếu với mẫu câu đã học trong SGK.\n⚠ (Miền 4: An toàn) Chơi theo nhóm thì thắng thua vui vẻ, không chê bạn trả lời sai; bảng điểm là để biết nhóm mình cần ôn gì, không phải để xếp hạng bạn nào giỏi bạn nào kém. Chỉ mở đúng đường dẫn trò chơi GV gửi, không mở sang trang khác; phần mềm hỏi tên thì dùng tên nhóm, không gõ họ tên đầy đủ của HS.","hs":"- HS tham gia bộ câu hỏi tương tác ôn Unit 6–10 trong “Review 2 (Fun time & Củng cố)” và chỉ ra được nhóm từ mình còn quên nhiều nhất.\n- HS giải thích được vì sao phải đối chiếu câu do công cụ dịch đưa ra với mẫu câu trong SGK."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":18,"tiet":1,"bai":"Ôn tập cuối học kì I","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá ngữ liệu và bốn kĩ năng, chuẩn bị kiểm tra định kì.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS làm được bài ôn tương tác của “Ôn tập cuối học kì I”, tự xác định ba phần còn yếu trong Unit 1–10 và chọn bài luyện tiếp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up","gv":"- GV cho HS chơi trò chơi/hỏi–đáp nhanh để huy động lại kiến thức đã học trong học kì.\n- Nêu mục tiêu tiết ôn tập, hệ thống các Unit trọng tâm chuẩn bị kiểm tra.","hs":"- HS tham gia, nhắc lại chủ đề – từ vựng; xác định nội dung cần ôn."},{"ten":"2. Ôn tập tổng hợp","gv":"- GV hệ thống từ vựng, mẫu câu, ngữ âm trọng tâm; luyện đề theo bốn kĩ năng.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Củng cố","gv":"- GV giải đáp thắc mắc, hướng dẫn cách làm từng dạng bài.","hs":"- HS luyện tập, ghi nhớ lưu ý."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) GV giao bộ bài tập tương tác có chấm tự động cho “Ôn tập cuối học kì I” với ngữ liệu Unit 1–10: nghe chọn đáp án, đọc đoạn rồi trả lời câu hỏi, sắp lại trật tự câu. HS tự làm, đọc kết quả từng câu, ghi ra ba phần mình sai nhiều nhất rồi chọn tiếp bài luyện đúng phần đó.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tự tra lại trong từ điển điện tử những từ của Unit 1–10 còn quên, đọc cả nghĩa lẫn ví dụ để chọn nghĩa hợp ngữ cảnh, nghe phát âm rồi sắp xếp bổ sung vào sổ tay từ vựng theo nhóm chủ đề để dễ ôn.\n⚠ (Miền 4: An toàn) Tự làm hết bài rồi mới xem đáp án; kết quả máy chấm là để biết mình hổng chỗ nào, không phải để so điểm với bạn. Chỉ mở đúng đường dẫn GV gửi, không mở sang mạng xã hội hay trò chơi trong giờ ôn. Không đăng nhập bằng tài khoản của bạn và không gõ họ tên đầy đủ, ngày sinh khi phần mềm hỏi.","hs":"- HS làm được bài ôn tương tác của “Ôn tập cuối học kì I”, tự xác định ba phần còn yếu trong Unit 1–10 và chọn bài luyện tiếp.\n- HS tra và sắp xếp bổ sung được từ còn quên vào sổ tay từ vựng theo nhóm chủ đề."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":18,"tiet":2,"bai":"Kiểm tra định kì cuối học kì I","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Đánh giá kết quả cuối học kì I qua bốn kĩ năng Nghe – Đọc – Nói – Viết theo ma trận đề phù hợp chuẩn đầu ra Tiếng Anh 5.\n2. Năng lực chung:\n- Tự chủ và tự học; Giải quyết vấn đề.\n3. Phẩm chất:\n- Trung thực, tự giác, nghiêm túc trong kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 6.1 CB2 (Hiểu biết về trí tuệ nhân tạo): HS thực hiện đúng quy định không dùng thiết bị số trong giờ kiểm tra, làm bài bằng năng lực của chính mình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Ổn định – Phổ biến","gv":"- GV ổn định lớp, tạo tâm lí thoải mái, tự tin trước khi làm bài.\n- Nhắc hình thức, thời gian và quy tắc làm bài kiểm tra; phát đề.","hs":"- HS chuẩn bị đồ dùng, giữ trật tự, lắng nghe hướng dẫn làm bài."},{"ten":"2. Làm bài / Thực hiện","gv":"- GV phát đề/tổ chức kiểm tra bốn kĩ năng; coi kiểm tra nghiêm túc.","hs":"- HS làm bài độc lập, trung thực."},{"ten":"3. Thu bài – Nhận xét","gv":"- GV thu bài, nhận xét chung tinh thần, thái độ làm bài.","hs":"- HS nộp bài, rút kinh nghiệm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) Tiết kiểm tra là dịp dạy chính về liêm chính học tập: GV nêu rõ công cụ dịch tự động và trợ lí trí tuệ nhân tạo có thể làm hộ cả bài nghe, đọc, viết, nhưng bài kiểm tra là để đo năng lực thật của chính HS; vì vậy trong giờ kiểm tra tuyệt đối không dùng thiết bị số.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Sau khi trả bài, GV hướng dẫn HS dùng từ điển Anh – Việt điện tử tra lại đúng những từ mình làm sai, nghe phát âm chuẩn và ghi vào sổ tay từ vựng của riêng mình.\n⚠ (Miền 4: An toàn) Không mang và không sử dụng thiết bị số trong giờ kiểm tra; không chụp đề bài gửi lên nhóm chat hay ứng dụng nào; không nhờ người khác làm hộ qua mạng.","hs":"- HS thực hiện đúng quy định không dùng thiết bị số trong giờ kiểm tra, làm bài bằng năng lực của chính mình.\n- HS nêu được vì sao nhờ công cụ dịch hay trợ lí AI làm hộ bài kiểm tra là không trung thực; sau khi trả bài mới dùng từ điển điện tử để học lại từ chưa biết."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":18,"tiet":3,"bai":"Chữa bài & củng cố sau kiểm tra học kì I","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá ngữ liệu và bốn kĩ năng, chuẩn bị kiểm tra định kì.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS tự lập được bảng lỗi theo bốn kĩ năng và chọn đúng bài tập tương tác để luyện lại phần yếu.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up","gv":"- GV nhận xét chung kết quả kiểm tra, động viên tinh thần học tập.\n- Dẫn vào tiết chữa bài – củng cố những nội dung HS còn sai sót.","hs":"- HS lắng nghe, đối chiếu bài làm, ghi nhận phần cần sửa."},{"ten":"2. Ôn tập tổng hợp","gv":"- GV hệ thống từ vựng, mẫu câu, ngữ âm trọng tâm; luyện đề theo bốn kĩ năng.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Củng cố","gv":"- GV giải đáp thắc mắc, hướng dẫn cách làm từng dạng bài.","hs":"- HS luyện tập, ghi nhớ lưu ý."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Trong tiết “Chữa bài & củng cố sau kiểm tra học kì I”, GV trả bài và hướng dẫn HS tự lập bảng lỗi của mình theo bốn kĩ năng nghe – đọc – nói – viết; mỗi ô lỗi HS chọn một bộ bài tập tương tác có chấm tự động do GV giao để luyện lại, làm xong biết ngay đúng sai và luyện tiếp cho tới khi làm đúng.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV chiếu một câu HS viết sai cạnh câu do công cụ dịch tự động sinh ra cho cùng ý đó; cả lớp đối chiếu với mẫu câu trong SGK và thấy câu của máy cũng chưa dùng được vì lệch nghĩa hoặc dùng cấu trúc chưa học. GV chốt lại nguyên tắc liêm chính: bài nộp phải do HS viết, công cụ dịch chỉ để tra một từ và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Bài làm và điểm số của mỗi bạn là chuyện riêng: không chụp bài của bạn, không đưa điểm lên nhóm chat, không so bì. Làm bài luyện tương tác thì tự làm hết rồi mới xem đáp án. Chỉ mở đúng đường dẫn GV gửi, không bấm vào quảng cáo và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự lập được bảng lỗi theo bốn kĩ năng và chọn đúng bài tập tương tác để luyện lại phần yếu.\n- HS nêu được nguyên tắc liêm chính khi dùng công cụ dịch: chỉ tra từ, không để máy viết hộ câu."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":18,"tiet":4,"bai":"Unit 11 — Lesson 1 (Family time) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về hoạt động cùng gia đình.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: cook meals, watch films, visit grandparents, go shopping; mẫu câu: What do you do with your family at the weekend? – We cook meals together.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được cook meals, watch films, visit grandparents, go shopping trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 11 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Family time”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 11.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: cook meals, watch films, visit grandparents, go shopping.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What do you do with your family at the weekend? – We cook meals together.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về hoạt động cùng gia đình).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 11 “Family time” cho HS nghe người bản ngữ đọc cook meals, watch films, visit grandparents, go shopping; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại cook meals, watch films, visit grandparents, go shopping vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được cook meals, watch films, visit grandparents, go shopping trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":19,"tiet":1,"bai":"Unit 11 — Lesson 1 (Family time) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về hoạt động cùng gia đình theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: cook meals, watch films, visit grandparents, go shopping; mẫu câu: What do you do with your family at the weekend? – We cook meals together.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Family time” (Unit 11) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 11.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"What do you do with your family at the weekend? – We cook meals together.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":19,"tiet":2,"bai":"Unit 11 — Lesson 2 (Family time) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về cảm xúc, tính từ chỉ trạng thái.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: happy, tired, excited, bored; feeling; mẫu câu: How do you feel now? – I feel happy.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 11 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Family time”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 11.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: happy, tired, excited, bored; feeling.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"How do you feel now? – I feel happy.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về cảm xúc, tính từ chỉ trạng thái.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":19,"tiet":3,"bai":"Unit 11 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /f/ trong family, film; chant về gia đình.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về cảm xúc, tính từ chỉ trạng thái.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: happy, tired, excited, bored; feeling; mẫu câu: How do you feel now? – I feel happy.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /f/ trong family, film.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 11) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 11.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /f/ trong family, film; chant về gia đình..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"How do you feel now? – I feel happy.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về cảm xúc, tính từ chỉ trạng thái.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 11 “Family time”: chiếu từ có gạch chân phần cần luyện (Âm /f/ trong family, film; chant về gia đình), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /f/ trong family, film; chant về gia đình của Unit 11 “Family time” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":19,"tiet":4,"bai":"Unit 11 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về thời gian bên gia đình, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 11; mẫu câu: đọc/viết về hoạt động gia đình vào cuối tuần.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 11 “Family time”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 11 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 11.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về thời gian bên gia đình; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 11 “Family time”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Family time để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 11 “Family time”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Family time và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":20,"tiet":1,"bai":"Unit 11 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết về hoạt động gia đình vào cuối tuần.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 11; mẫu câu: đọc/viết về hoạt động gia đình vào cuối tuần.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Family time bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 11) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 11.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết về hoạt động gia đình vào cuối tuần.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 11 “Family time”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Family time; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 11 “Family time” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Family time bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":20,"tiet":2,"bai":"Unit 12 — Lesson 1 (Our Tet holiday) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về chuẩn bị Tết.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: clean the house, buy flowers, make cakes, decorate the house; mẫu câu: What do you do at Tet? – I help my mum make cakes.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được clean the house, buy flowers, make cakes, decorate the house trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 12 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our Tet holiday”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 12.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: clean the house, buy flowers, make cakes, decorate the house.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What do you do at Tet? – I help my mum make cakes.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về chuẩn bị Tết).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 12 “Our Tet holiday” cho HS nghe người bản ngữ đọc clean the house, buy flowers, make cakes, decorate the house; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại clean the house, buy flowers, make cakes, decorate the house vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được clean the house, buy flowers, make cakes, decorate the house trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":20,"tiet":3,"bai":"Unit 12 — Lesson 1 (Our Tet holiday) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về chuẩn bị Tết theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: clean the house, buy flowers, make cakes, decorate the house; mẫu câu: What do you do at Tet? – I help my mum make cakes.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Our Tet holiday” (Unit 12) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 12.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"What do you do at Tet? – I help my mum make cakes.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":20,"tiet":4,"bai":"Unit 12 — Lesson 2 (Our Tet holiday) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về phong tục, lời chúc Tết.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: lucky money, visit relatives, Happy New Year; mẫu câu: What will you do at Tet? – I'll visit my relatives.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 12 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our Tet holiday”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 12.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: lucky money, visit relatives, Happy New Year.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"What will you do at Tet? – I'll visit my relatives.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về phong tục, lời chúc Tết.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":21,"tiet":1,"bai":"Unit 12 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /t/ trong Tet; chant về ngày Tết (giữ nét văn hoá Việt).).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về phong tục, lời chúc Tết.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: lucky money, visit relatives, Happy New Year; mẫu câu: What will you do at Tet? – I'll visit my relatives.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /t/ trong Tet.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 12) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 12.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /t/ trong Tet; chant về ngày Tết (giữ nét văn hoá Việt)..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"What will you do at Tet? – I'll visit my relatives.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về phong tục, lời chúc Tết.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 12 “Our Tet holiday”: chiếu từ có gạch chân phần cần luyện (Âm /t/ trong Tet; chant về ngày Tết (giữ nét văn hoá Việt), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /t/ trong Tet; chant về ngày Tết (giữ nét văn hoá Việt của Unit 12 “Our Tet holiday” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":21,"tiet":2,"bai":"Unit 12 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về ngày Tết, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 12; mẫu câu: đọc/viết về hoạt động của em trong dịp Tết.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 12 “Our Tet holiday”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 12 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 12.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về ngày Tết; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 12 “Our Tet holiday”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Our Tet holiday để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 12 “Our Tet holiday”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Our Tet holiday và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":21,"tiet":3,"bai":"Unit 12 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết về hoạt động của em trong dịp Tết.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 12; mẫu câu: đọc/viết về hoạt động của em trong dịp Tết.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Our Tet holiday bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 12) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 12.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết về hoạt động của em trong dịp Tết.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 12 “Our Tet holiday”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Our Tet holiday; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 12 “Our Tet holiday” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Our Tet holiday bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":21,"tiet":4,"bai":"Unit 13 — Lesson 1 (Our special days) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về ngày lễ, ngày đặc biệt.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: birthday, Teachers' Day, Mid-Autumn Festival, Independence Day; mẫu câu: What special day do you like? – I like the Mid-Autumn Festival.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được birthday, Teachers' Day, Mid-Autumn Festival, Independence Day trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 13 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our special days”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 13.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: birthday, Teachers' Day, Mid-Autumn Festival, Independence Day.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What special day do you like? – I like the Mid-Autumn Festival.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về ngày lễ, ngày đặc biệt).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 13 “Our special days” cho HS nghe người bản ngữ đọc birthday, Teachers' Day, Mid-Autumn Festival, Independence Day; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại birthday, Teachers' Day, Mid-Autumn Festival, Independence Day vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được birthday, Teachers' Day, Mid-Autumn Festival, Independence Day trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":22,"tiet":1,"bai":"Unit 13 — Lesson 1 (Our special days) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về ngày lễ, ngày đặc biệt theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: birthday, Teachers' Day, Mid-Autumn Festival, Independence Day; mẫu câu: What special day do you like? – I like the Mid-Autumn Festival.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Our special days” (Unit 13) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 13.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"What special day do you like? – I like the Mid-Autumn Festival.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":22,"tiet":2,"bai":"Unit 13 — Lesson 2 (Our special days) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về thời gian, hoạt động ngày lễ.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: months of the year; in September; give flowers, watch fireworks; mẫu câu: When is Teachers' Day? – It's on the 20th of November.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 13 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our special days”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 13.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: months of the year; in September; give flowers, watch fireworks.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"When is Teachers' Day? – It's on the 20th of November.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về thời gian, hoạt động ngày lễ.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":22,"tiet":3,"bai":"Unit 13 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /θ/ trong month, birthday; chant về ngày đặc biệt.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về thời gian, hoạt động ngày lễ.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: months of the year; in September; give flowers, watch fireworks; mẫu câu: When is Teachers' Day? – It's on the 20th of November.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /θ/ trong month, birthday.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 13) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 13.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /θ/ trong month, birthday; chant về ngày đặc biệt..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"When is Teachers' Day? – It's on the 20th of November.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về thời gian, hoạt động ngày lễ.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 13 “Our special days”: chiếu từ có gạch chân phần cần luyện (Âm /θ/ trong month, birthday; chant về ngày đặc biệt), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /θ/ trong month, birthday; chant về ngày đặc biệt của Unit 13 “Our special days” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":22,"tiet":4,"bai":"Unit 13 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về ngày đặc biệt, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 13; mẫu câu: đọc/viết về một ngày đặc biệt em yêu thích.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 13 “Our special days”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 13 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 13.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về ngày đặc biệt; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 13 “Our special days”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Our special days để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 13 “Our special days”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Our special days và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":23,"tiet":1,"bai":"Unit 13 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết về một ngày đặc biệt em yêu thích.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 13; mẫu câu: đọc/viết về một ngày đặc biệt em yêu thích.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Our special days bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 13) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 13.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết về một ngày đặc biệt em yêu thích.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 13 “Our special days”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Our special days; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 13 “Our special days” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Our special days bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":23,"tiet":2,"bai":"Unit 14 — Lesson 1 (Staying healthy) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về thói quen giữ sức khoẻ.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: eat vegetables, drink water, do exercise, brush teeth; mẫu câu: What do you do to stay healthy? – I eat a lot of vegetables.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được eat vegetables, drink water, do exercise, brush teeth trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 14 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Staying healthy”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 14.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: eat vegetables, drink water, do exercise, brush teeth.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What do you do to stay healthy? – I eat a lot of vegetables.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về thói quen giữ sức khoẻ).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 14 “Staying healthy” cho HS nghe người bản ngữ đọc eat vegetables, drink water, do exercise, brush teeth; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại eat vegetables, drink water, do exercise, brush teeth vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được eat vegetables, drink water, do exercise, brush teeth trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":23,"tiet":3,"bai":"Unit 14 — Lesson 1 (Staying healthy) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về thói quen giữ sức khoẻ theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: eat vegetables, drink water, do exercise, brush teeth; mẫu câu: What do you do to stay healthy? – I eat a lot of vegetables.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Staying healthy” (Unit 14) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 14.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"What do you do to stay healthy? – I eat a lot of vegetables.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":23,"tiet":4,"bai":"Unit 14 — Lesson 2 (Staying healthy) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về lời khuyên sức khoẻ.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: should, shouldn't; eat sweets, stay up late; mẫu câu: What should you do to stay healthy? – I should do exercise every day.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 14 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Staying healthy”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 14.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: should, shouldn't; eat sweets, stay up late.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"What should you do to stay healthy? – I should do exercise every day.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về lời khuyên sức khoẻ.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":24,"tiet":1,"bai":"Unit 14 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /h/ trong healthy, habit; chant giữ sức khoẻ.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về lời khuyên sức khoẻ.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: should, shouldn't; eat sweets, stay up late; mẫu câu: What should you do to stay healthy? – I should do exercise every day.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /h/ trong healthy, habit.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 14) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 14.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /h/ trong healthy, habit; chant giữ sức khoẻ..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"What should you do to stay healthy? – I should do exercise every day.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về lời khuyên sức khoẻ.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 14 “Staying healthy”: chiếu từ có gạch chân phần cần luyện (Âm /h/ trong healthy, habit; chant giữ sức khoẻ), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /h/ trong healthy, habit; chant giữ sức khoẻ của Unit 14 “Staying healthy” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":24,"tiet":2,"bai":"Unit 14 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về giữ sức khoẻ, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 14; mẫu câu: đọc/viết về thói quen giữ gìn sức khoẻ.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 14 “Staying healthy”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 14 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 14.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về giữ sức khoẻ; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 14 “Staying healthy”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Staying healthy để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 14 “Staying healthy”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Staying healthy và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":24,"tiet":3,"bai":"Unit 14 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết về thói quen giữ gìn sức khoẻ.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 14; mẫu câu: đọc/viết về thói quen giữ gìn sức khoẻ.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Staying healthy bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 14) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 14.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết về thói quen giữ gìn sức khoẻ.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 14 “Staying healthy”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Staying healthy; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 14 “Staying healthy” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Staying healthy bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":24,"tiet":4,"bai":"Unit 15 — Lesson 1 (Our health) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về triệu chứng, ốm đau.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: a headache, a toothache, a cough, a fever; ill; mẫu câu: What's the matter with you? – I have a headache.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được a headache, a toothache, a cough, a fever.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 15 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our health”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 15.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: a headache, a toothache, a cough, a fever; ill.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What's the matter with you? – I have a headache.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về triệu chứng, ốm đau).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 15 “Our health” cho HS nghe người bản ngữ đọc a headache, a toothache, a cough, a fever; ill; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại a headache, a toothache, a cough, a fever; ill vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được a headache, a toothache, a cough, a fever; ill trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":25,"tiet":1,"bai":"Unit 15 — Lesson 1 (Our health) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về triệu chứng, ốm đau theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: a headache, a toothache, a cough, a fever; ill; mẫu câu: What's the matter with you? – I have a headache.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Our health” (Unit 15) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 15.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"What's the matter with you? – I have a headache.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":25,"tiet":2,"bai":"Unit 15 — Lesson 2 (Our health) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về lời khuyên khi ốm.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: see a doctor, take medicine, have a rest, keep warm; mẫu câu: You should see a doctor.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 15 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our health”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 15.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: see a doctor, take medicine, have a rest, keep warm.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"You should see a doctor.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về lời khuyên khi ốm.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":25,"tiet":3,"bai":"Unit 15 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /ɔː/ trong cough, sore; chant về sức khoẻ.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về lời khuyên khi ốm.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: see a doctor, take medicine, have a rest, keep warm; mẫu câu: You should see a doctor.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /ɔː/ trong cough, sore.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 15) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 15.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /ɔː/ trong cough, sore; chant về sức khoẻ..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"You should see a doctor.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về lời khuyên khi ốm.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 15 “Our health”: chiếu từ có gạch chân phần cần luyện (Âm /ɔː/ trong cough, sore; chant về sức khoẻ), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /ɔː/ trong cough, sore; chant về sức khoẻ của Unit 15 “Our health” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":25,"tiet":4,"bai":"Unit 15 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về sức khoẻ, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 15; mẫu câu: đọc/viết lời khuyên chăm sóc sức khoẻ.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 15 “Our health”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 15 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 15.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về sức khoẻ; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 15 “Our health”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Our health để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 15 “Our health”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Our health và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":26,"tiet":1,"bai":"Unit 15 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết lời khuyên chăm sóc sức khoẻ.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 15; mẫu câu: đọc/viết lời khuyên chăm sóc sức khoẻ.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Our health bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 15) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 15.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết lời khuyên chăm sóc sức khoẻ.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 15 “Our health”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Our health; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 15 “Our health” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Our health bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":26,"tiet":2,"bai":"Review 3 (Ôn tập – Nghe – Đọc)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá và củng cố ngữ liệu (từ vựng, mẫu câu) qua kĩ năng Nghe – Đọc của các Unit đã học.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề và sáng tạo.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực trong ôn tập và kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS làm được bài ôn tương tác của “Review 3 (Ôn tập – Nghe – Đọc)”, tự xác định ba phần còn yếu trong Unit 11–15 và chọn bài luyện tiếp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 11–15.\n- Nêu mục tiêu Review 3: củng cố kĩ năng Nghe và Đọc.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 11–15.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn tập theo kĩ năng","gv":"- GV tổ chức ôn Nghe – Đọc qua hệ thống bài tập (Listen/Read/Speak/Write) trong phần Review.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập theo cặp/nhóm, vận dụng ngữ liệu tổng hợp.","hs":"- HS thực hành, sửa lỗi cho nhau."},{"ten":"4. Fun time / Củng cố","gv":"- GV tổ chức trò chơi/hoạt động Fun time; tổng kết kiến thức trọng tâm.","hs":"- HS tham gia, hệ thống lại ngữ liệu đã ôn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) GV giao bộ bài tập tương tác có chấm tự động cho “Review 3 (Ôn tập – Nghe – Đọc)” với ngữ liệu Unit 11–15: nghe chọn đáp án, đọc đoạn rồi trả lời câu hỏi, sắp lại trật tự câu. HS tự làm, đọc kết quả từng câu, ghi ra ba phần mình sai nhiều nhất rồi chọn tiếp bài luyện đúng phần đó.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tự tra lại trong từ điển điện tử những từ của Unit 11–15 còn quên, đọc cả nghĩa lẫn ví dụ để chọn nghĩa hợp ngữ cảnh, nghe phát âm rồi sắp xếp bổ sung vào sổ tay từ vựng theo nhóm chủ đề để dễ ôn.\n⚠ (Miền 4: An toàn) Tự làm hết bài rồi mới xem đáp án; kết quả máy chấm là để biết mình hổng chỗ nào, không phải để so điểm với bạn. Chỉ mở đúng đường dẫn GV gửi, không mở sang mạng xã hội hay trò chơi trong giờ ôn. Không đăng nhập bằng tài khoản của bạn và không gõ họ tên đầy đủ, ngày sinh khi phần mềm hỏi.","hs":"- HS làm được bài ôn tương tác của “Review 3 (Ôn tập – Nghe – Đọc)”, tự xác định ba phần còn yếu trong Unit 11–15 và chọn bài luyện tiếp.\n- HS tra và sắp xếp bổ sung được từ còn quên vào sổ tay từ vựng theo nhóm chủ đề."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":26,"tiet":3,"bai":"Review 3 (Ôn tập – Nói – Viết)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá và củng cố ngữ liệu (từ vựng, mẫu câu) qua kĩ năng Nói – Viết của các Unit đã học.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề và sáng tạo.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực trong ôn tập và kiểm tra – đánh giá.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 11–15.\n- Nêu mục tiêu Review 3: củng cố kĩ năng Nói và Viết.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 11–15.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn tập theo kĩ năng","gv":"- GV tổ chức ôn Nói – Viết qua hệ thống bài tập (Listen/Read/Speak/Write) trong phần Review.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập theo cặp/nhóm, vận dụng ngữ liệu tổng hợp.","hs":"- HS thực hành, sửa lỗi cho nhau."},{"ten":"4. Fun time / Củng cố","gv":"- GV tổ chức trò chơi/hoạt động Fun time; tổng kết kiến thức trọng tâm.","hs":"- HS tham gia, hệ thống lại ngữ liệu đã ôn."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":26,"tiet":4,"bai":"Review 3 (Fun time & Củng cố)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá và củng cố ngữ liệu (từ vựng, mẫu câu) qua kĩ năng tổng hợp của các Unit đã học.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề và sáng tạo.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực trong ôn tập và kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS tham gia bộ câu hỏi tương tác ôn Unit 11–15 trong “Review 3 (Fun time & Củng cố)” và chỉ ra được nhóm từ mình còn quên nhiều nhất.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 11–15.\n- Nêu mục tiêu Review 3: củng cố trò chơi ngôn ngữ, hệ thống hoá từ vựng – mẫu câu.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 11–15.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn tập theo kĩ năng","gv":"- GV tổ chức ôn tổng hợp qua hệ thống bài tập (Listen/Read/Speak/Write) trong phần Review.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập theo cặp/nhóm, vận dụng ngữ liệu tổng hợp.","hs":"- HS thực hành, sửa lỗi cho nhau."},{"ten":"4. Fun time / Củng cố","gv":"- GV tổ chức trò chơi/hoạt động Fun time; tổng kết kiến thức trọng tâm.","hs":"- HS tham gia, hệ thống lại ngữ liệu đã ôn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) GV tổ chức phần Fun time của “Review 3 (Fun time & Củng cố)” bằng bộ câu hỏi tương tác chấm tự động cho ngữ liệu Unit 11–15: nghe đoán từ, ghép câu, đoán chữ; HS chơi theo nhóm, nhìn bảng điểm hiện ngay trên màn hình và tự chỉ ra nhóm từ nào cả nhóm còn quên nhiều nhất.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ một câu ôn tập của Unit 11–15 vào công cụ dịch tự động rồi dịch ngược lại tiếng Việt, chiếu cả hai chiều cho HS thấy nghĩa đã lệch đi thế nào; HS giải thích vì sao không nên tin ngay câu máy dịch mà phải đối chiếu với mẫu câu đã học trong SGK.\n⚠ (Miền 4: An toàn) Chơi theo nhóm thì thắng thua vui vẻ, không chê bạn trả lời sai; bảng điểm là để biết nhóm mình cần ôn gì, không phải để xếp hạng bạn nào giỏi bạn nào kém. Chỉ mở đúng đường dẫn trò chơi GV gửi, không mở sang trang khác; phần mềm hỏi tên thì dùng tên nhóm, không gõ họ tên đầy đủ của HS.","hs":"- HS tham gia bộ câu hỏi tương tác ôn Unit 11–15 trong “Review 3 (Fun time & Củng cố)” và chỉ ra được nhóm từ mình còn quên nhiều nhất.\n- HS giải thích được vì sao phải đối chiếu câu do công cụ dịch đưa ra với mẫu câu trong SGK."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":27,"tiet":1,"bai":"Kiểm tra định kì giữa học kì II","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Đánh giá kết quả giữa học kì II qua bốn kĩ năng Nghe – Đọc – Nói – Viết theo ma trận đề phù hợp chuẩn đầu ra Tiếng Anh 5.\n2. Năng lực chung:\n- Tự chủ và tự học; Giải quyết vấn đề.\n3. Phẩm chất:\n- Trung thực, tự giác, nghiêm túc trong kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 6.1 CB2 (Hiểu biết về trí tuệ nhân tạo): HS thực hiện đúng quy định không dùng thiết bị số trong giờ kiểm tra, làm bài bằng năng lực của chính mình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Ổn định – Phổ biến","gv":"- GV ổn định lớp, tạo tâm lí thoải mái, tự tin trước khi làm bài.\n- Nhắc hình thức, thời gian và quy tắc làm bài kiểm tra; phát đề.","hs":"- HS chuẩn bị đồ dùng, giữ trật tự, lắng nghe hướng dẫn làm bài."},{"ten":"2. Làm bài / Thực hiện","gv":"- GV phát đề/tổ chức kiểm tra bốn kĩ năng; coi kiểm tra nghiêm túc.","hs":"- HS làm bài độc lập, trung thực."},{"ten":"3. Thu bài – Nhận xét","gv":"- GV thu bài, nhận xét chung tinh thần, thái độ làm bài.","hs":"- HS nộp bài, rút kinh nghiệm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) Tiết kiểm tra là dịp dạy chính về liêm chính học tập: GV nêu rõ công cụ dịch tự động và trợ lí trí tuệ nhân tạo có thể làm hộ cả bài nghe, đọc, viết, nhưng bài kiểm tra là để đo năng lực thật của chính HS; vì vậy trong giờ kiểm tra tuyệt đối không dùng thiết bị số.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Sau khi trả bài, GV hướng dẫn HS dùng từ điển Anh – Việt điện tử tra lại đúng những từ mình làm sai, nghe phát âm chuẩn và ghi vào sổ tay từ vựng của riêng mình.\n⚠ (Miền 4: An toàn) Không mang và không sử dụng thiết bị số trong giờ kiểm tra; không chụp đề bài gửi lên nhóm chat hay ứng dụng nào; không nhờ người khác làm hộ qua mạng.","hs":"- HS thực hiện đúng quy định không dùng thiết bị số trong giờ kiểm tra, làm bài bằng năng lực của chính mình.\n- HS nêu được vì sao nhờ công cụ dịch hay trợ lí AI làm hộ bài kiểm tra là không trung thực; sau khi trả bài mới dùng từ điển điện tử để học lại từ chưa biết."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":27,"tiet":2,"bai":"Unit 16 — Lesson 1 (Seasons and the weather) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về các mùa và thời tiết.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: spring, summer, autumn, winter; hot, cold, sunny, rainy, windy; mẫu câu: What's the weather like in summer? – It's hot and sunny.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được spring, summer, autumn, winter.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 16 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Seasons and the weather”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 16.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: spring, summer, autumn, winter; hot, cold, sunny, rainy, windy.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What's the weather like in summer? – It's hot and sunny.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về các mùa và thời tiết).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 16 “Seasons and the weather” cho HS nghe người bản ngữ đọc spring, summer, autumn, winter; hot, cold, sunny, rainy, windy; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại spring, summer, autumn, winter; hot, cold, sunny, rainy, windy vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được spring, summer, autumn, winter; hot, cold, sunny, rainy, windy trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":27,"tiet":3,"bai":"Unit 16 — Lesson 1 (Seasons and the weather) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về các mùa và thời tiết theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: spring, summer, autumn, winter; hot, cold, sunny, rainy, windy; mẫu câu: What's the weather like in summer? – It's hot and sunny.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Seasons and the weather” (Unit 16) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 16.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"What's the weather like in summer? – It's hot and sunny.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":27,"tiet":4,"bai":"Unit 16 — Lesson 2 (Seasons and the weather) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về hoạt động theo mùa.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: go swimming, wear a coat, fly kites; because; mẫu câu: Which season do you like? – I like autumn because it's cool.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 16 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Seasons and the weather”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 16.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: go swimming, wear a coat, fly kites; because.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"Which season do you like? – I like autumn because it's cool.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về hoạt động theo mùa.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":28,"tiet":1,"bai":"Unit 16 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /s/ /z/ trong season, snows; chant về bốn mùa.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về hoạt động theo mùa.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: go swimming, wear a coat, fly kites; because; mẫu câu: Which season do you like? – I like autumn because it's cool.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /s/ /z/ trong season, snows.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 16) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 16.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /s/ /z/ trong season, snows; chant về bốn mùa..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"Which season do you like? – I like autumn because it's cool.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về hoạt động theo mùa.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 16 “Seasons and the weather”: chiếu từ có gạch chân phần cần luyện (Âm /s/ /z/ trong season, snows; chant về bốn mùa), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /s/ /z/ trong season, snows; chant về bốn mùa của Unit 16 “Seasons and the weather” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":28,"tiet":2,"bai":"Unit 16 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về thời tiết, các mùa, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 16; mẫu câu: đọc/viết về mùa và thời tiết em yêu thích.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 16 “Seasons and the weather”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 16 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 16.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về thời tiết, các mùa; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 16 “Seasons and the weather”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Seasons and the weather để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 16 “Seasons and the weather”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Seasons and the weather và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":28,"tiet":3,"bai":"Unit 16 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết về mùa và thời tiết em yêu thích.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 16; mẫu câu: đọc/viết về mùa và thời tiết em yêu thích.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Seasons and the weather bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 16) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 16.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết về mùa và thời tiết em yêu thích.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 16 “Seasons and the weather”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Seasons and the weather; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 16 “Seasons and the weather” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Seasons and the weather bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":28,"tiet":4,"bai":"Unit 17 — Lesson 1 (Stories for children) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về truyện thiếu nhi, nhân vật.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: fairy tale, folk tale; princess, fox, tortoise, hare; mẫu câu: What's your favourite story? – It's The Fox and the Crow.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được fairy tale, folk tale.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 17 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Stories for children”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 17.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: fairy tale, folk tale; princess, fox, tortoise, hare.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What's your favourite story? – It's The Fox and the Crow.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về truyện thiếu nhi, nhân vật).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 17 “Stories for children” cho HS nghe người bản ngữ đọc fairy tale, folk tale; princess, fox, tortoise, hare; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại fairy tale, folk tale; princess, fox, tortoise, hare vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được fairy tale, folk tale; princess, fox, tortoise, hare trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":29,"tiet":1,"bai":"Unit 17 — Lesson 1 (Stories for children) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về truyện thiếu nhi, nhân vật theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: fairy tale, folk tale; princess, fox, tortoise, hare; mẫu câu: What's your favourite story? – It's The Fox and the Crow.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Stories for children” (Unit 17) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 17.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"What's your favourite story? – It's The Fox and the Crow.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":29,"tiet":2,"bai":"Unit 17 — Lesson 2 (Stories for children) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về tính cách nhân vật, bài học.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: clever, kind, greedy, lazy; character; mẫu câu: What's the fox like? – It's clever.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 17 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Stories for children”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 17.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: clever, kind, greedy, lazy; character.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"What's the fox like? – It's clever.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về tính cách nhân vật, bài học.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":29,"tiet":3,"bai":"Unit 17 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /tʃ/ trong children, character; chant về truyện.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về tính cách nhân vật, bài học.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: clever, kind, greedy, lazy; character; mẫu câu: What's the fox like? – It's clever.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /tʃ/ trong children, character.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 17) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 17.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /tʃ/ trong children, character; chant về truyện..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"What's the fox like? – It's clever.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về tính cách nhân vật, bài học.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 17 “Stories for children”: chiếu từ có gạch chân phần cần luyện (Âm /tʃ/ trong children, character; chant về truyện), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /tʃ/ trong children, character; chant về truyện của Unit 17 “Stories for children” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":29,"tiet":4,"bai":"Unit 17 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về truyện thiếu nhi, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 17; mẫu câu: đọc/viết giới thiệu một truyện em thích và bài học.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 17 “Stories for children”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 17 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 17.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về truyện thiếu nhi; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 17 “Stories for children”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Stories for children để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 17 “Stories for children”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Stories for children và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":30,"tiet":1,"bai":"Unit 17 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết giới thiệu một truyện em thích và bài học.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 17; mẫu câu: đọc/viết giới thiệu một truyện em thích và bài học.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Stories for children bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 17) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 17.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết giới thiệu một truyện em thích và bài học.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 17 “Stories for children”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Stories for children; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 17 “Stories for children” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Stories for children bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":30,"tiet":2,"bai":"Unit 18 — Lesson 1 (Means of transport) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về phương tiện giao thông.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: bus, train, plane, ship, underground; means of transport; mẫu câu: How do you go to school? – I go to school by bike.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được bus, train, plane, ship, underground.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 18 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Means of transport”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 18.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: bus, train, plane, ship, underground; means of transport.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"How do you go to school? – I go to school by bike.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về phương tiện giao thông).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 18 “Means of transport” cho HS nghe người bản ngữ đọc bus, train, plane, ship, underground; means of transport; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại bus, train, plane, ship, underground; means of transport vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được bus, train, plane, ship, underground; means of transport trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":30,"tiet":3,"bai":"Unit 18 — Lesson 1 (Means of transport) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về phương tiện giao thông theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: bus, train, plane, ship, underground; means of transport; mẫu câu: How do you go to school? – I go to school by bike.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Means of transport” (Unit 18) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 18.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"How do you go to school? – I go to school by bike.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":30,"tiet":4,"bai":"Unit 18 — Lesson 2 (Means of transport) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về ưu, nhược điểm phương tiện.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: fast, slow, cheap, expensive, safe; mẫu câu: What's the plane like? – It's fast but expensive.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 18 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Means of transport”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 18.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: fast, slow, cheap, expensive, safe.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"What's the plane like? – It's fast but expensive.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về ưu, nhược điểm phương tiện.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":31,"tiet":1,"bai":"Unit 18 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /tr/ trong train, transport; chant về phương tiện.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về ưu, nhược điểm phương tiện.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: fast, slow, cheap, expensive, safe; mẫu câu: What's the plane like? – It's fast but expensive.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /tr/ trong train, transport.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 18) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 18.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /tr/ trong train, transport; chant về phương tiện..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"What's the plane like? – It's fast but expensive.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về ưu, nhược điểm phương tiện.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 18 “Means of transport”: chiếu từ có gạch chân phần cần luyện (Âm /tr/ trong train, transport; chant về phương tiện), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /tr/ trong train, transport; chant về phương tiện của Unit 18 “Means of transport” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":31,"tiet":2,"bai":"Unit 18 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về phương tiện đi lại, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 18; mẫu câu: đọc/viết về phương tiện em thường dùng và lí do.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 18 “Means of transport”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 18 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 18.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về phương tiện đi lại; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 18 “Means of transport”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Means of transport để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 18 “Means of transport”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Means of transport và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":31,"tiet":3,"bai":"Unit 18 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết về phương tiện em thường dùng và lí do.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 18; mẫu câu: đọc/viết về phương tiện em thường dùng và lí do.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Means of transport bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 18) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 18.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết về phương tiện em thường dùng và lí do.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 18 “Means of transport”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Means of transport; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 18 “Means of transport” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Means of transport bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":31,"tiet":4,"bai":"Unit 19 — Lesson 1 (Places of interest) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về địa danh, thắng cảnh.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: beach, mountain, lake, temple, historical site; place of interest; mẫu câu: Where would you like to visit? – I'd like to visit Ha Long Bay.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được beach, mountain, lake, temple, historical site.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 19 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Places of interest”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 19.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: beach, mountain, lake, temple, historical site; place of interest.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Where would you like to visit? – I'd like to visit Ha Long Bay.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về địa danh, thắng cảnh).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 19 “Places of interest” cho HS nghe người bản ngữ đọc beach, mountain, lake, temple, historical site; place of interest; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại beach, mountain, lake, temple, historical site; place of interest vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được beach, mountain, lake, temple, historical site; place of interest trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":32,"tiet":1,"bai":"Unit 19 — Lesson 1 (Places of interest) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về địa danh, thắng cảnh theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: beach, mountain, lake, temple, historical site; place of interest; mẫu câu: Where would you like to visit? – I'd like to visit Ha Long Bay.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Places of interest” (Unit 19) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 19.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"Where would you like to visit? – I'd like to visit Ha Long Bay.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":32,"tiet":2,"bai":"Unit 19 — Lesson 2 (Places of interest) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về hoạt động tại điểm tham quan.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: take photos, go sightseeing, climb the mountain; mẫu câu: What can you do there? – You can go sightseeing and take photos.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 19 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Places of interest”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 19.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: take photos, go sightseeing, climb the mountain.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"What can you do there? – You can go sightseeing and take photos.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về hoạt động tại điểm tham quan.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":32,"tiet":3,"bai":"Unit 19 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /pl/ trong place; chant về thắng cảnh (Nghệ An/Việt Nam).).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về hoạt động tại điểm tham quan.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: take photos, go sightseeing, climb the mountain; mẫu câu: What can you do there? – You can go sightseeing and take photos.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /pl/ trong place.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 19) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 19.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /pl/ trong place; chant về thắng cảnh (Nghệ An/Việt Nam)..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"What can you do there? – You can go sightseeing and take photos.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về hoạt động tại điểm tham quan.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 19 “Places of interest”: chiếu từ có gạch chân phần cần luyện (Âm /pl/ trong place; chant về thắng cảnh (Nghệ An/Việt Nam), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /pl/ trong place; chant về thắng cảnh (Nghệ An/Việt Nam của Unit 19 “Places of interest” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":32,"tiet":4,"bai":"Unit 19 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về địa danh, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 19; mẫu câu: đọc/viết giới thiệu một thắng cảnh em muốn đến.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 19 “Places of interest”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 19 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 19.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về địa danh; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 19 “Places of interest”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Places of interest để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 19 “Places of interest”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Places of interest và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":33,"tiet":1,"bai":"Unit 19 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết giới thiệu một thắng cảnh em muốn đến.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 19; mẫu câu: đọc/viết giới thiệu một thắng cảnh em muốn đến.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Places of interest bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 19) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 19.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết giới thiệu một thắng cảnh em muốn đến.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 19 “Places of interest”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Places of interest; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 19 “Places of interest” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Places of interest bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":33,"tiet":2,"bai":"Unit 20 — Lesson 1 (Our summer holidays) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết từ vựng, mẫu câu mới về kế hoạch nghỉ hè.\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: go to the beach, visit grandparents, go camping; summer holiday; mẫu câu: What are you going to do this summer? – I'm going to go to the beach.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS tự tra được go to the beach, visit grandparents, go camping.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 20 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our summer holidays”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 20.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: go to the beach, visit grandparents, go camping; summer holiday.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What are you going to do this summer? – I'm going to go to the beach.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu.\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác về kế hoạch nghỉ hè).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Look, listen and repeat của Unit 20 “Our summer holidays” cho HS nghe người bản ngữ đọc go to the beach, visit grandparents, go camping; summer holiday; sau đó HS tự tra từng từ trong từ điển Anh – Việt điện tử, nghe phát âm, đọc thêm phần ví dụ để biết từ đó đi với những từ nào rồi ghi vào sổ tay từ vựng.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS đọc lại go to the beach, visit grandparents, go camping; summer holiday vào phần luyện phát âm của ứng dụng do GV chỉ định, xem máy báo mình đọc khớp tới đâu, chọn ra 2-3 từ mình đọc kém nhất để luyện thêm. GV nhắc: máy chấm theo giọng chuẩn nên có thể chấm sai với giọng vùng miền, tai của GV và của bạn mới là người quyết định.\n⚠ (Miền 4: An toàn) Chỉ mở đúng ứng dụng và trang từ điển GV chỉ định, không mở sang trang khác trong giờ. Khi ứng dụng xin quyền dùng micrô thì GV là người đồng ý và tắt quyền sau khi học xong; HS không thu âm giọng bạn rồi gửi đi đâu. Không bấm vào quảng cáo, không tải phần mềm lạ và không đăng nhập bằng tài khoản của người khác.","hs":"- HS tự tra được go to the beach, visit grandparents, go camping; summer holiday trong từ điển điện tử, nghe phát âm và ghi cả ví dụ vào sổ tay từ vựng.\n- HS chọn được 2-3 từ mình đọc còn kém để luyện thêm và hiểu vì sao không tin tuyệt đối vào điểm máy chấm."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":33,"tiet":3,"bai":"Unit 20 — Lesson 1 (Our summer holidays) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nói: luyện nói thành thạo mẫu câu về kế hoạch nghỉ hè theo cặp/nhóm.\n- Nghe: nghe hiểu và hoàn thành bài tập nghe.\n- Đọc–Viết: đọc hiểu và viết câu vận dụng ngữ liệu đã học.\nNgữ liệu trọng tâm: go to the beach, visit grandparents, go camping; summer holiday; mẫu câu: What are you going to do this summer? – I'm going to go to the beach.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Our summer holidays” (Unit 20) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 20.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Practice (Luyện tập)","gv":"- GV cho HS nghe và làm bài tập nghe (Listen and tick/number); chữa bài.\n- Tổ chức Let's talk: luyện nói mẫu câu \"What are you going to do this summer? – I'm going to go to the beach.\".","hs":"- HS nghe, làm bài, đối chiếu đáp án.\n- Luyện nói theo cặp/nhóm."},{"ten":"3. Read & Write (Đọc – Viết)","gv":"- GV cho HS đọc và hoàn thành câu (Read and complete), viết câu vận dụng.","hs":"- HS đọc, điền từ, viết câu ngắn theo mẫu."},{"ten":"4. Production – Let's sing (Vận dụng)","gv":"- GV cho HS hát/đọc chant củng cố ngữ liệu; khuyến khích vận dụng nói tự nhiên.","hs":"- HS hát/đọc chant, vận dụng mẫu câu giao tiếp."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":33,"tiet":4,"bai":"Unit 20 — Lesson 2 (Our summer holidays) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết mẫu câu mới về nơi đến, hoạt động hè.\n- Nói: hỏi–đáp dùng mẫu câu mở rộng; phát âm đúng.\n- Đọc: đọc và nhận diện ngữ liệu mới.\n- Viết: viết câu ngắn theo mẫu.\nNgữ liệu trọng tâm: stay at home, travel to; with my family; mẫu câu: Where are you going to go? – I'm going to travel to Da Nang.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 20 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Our summer holidays”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 20.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV giới thiệu từ mới: stay at home, travel to; with my family.\n- Đọc mẫu, cho HS nghe audio, nhắc lại.\n- Giới thiệu mẫu câu: \"Where are you going to go? – I'm going to travel to Da Nang.\".","hs":"- HS quan sát, nghe và nhắc lại; hiểu nghĩa qua tranh/ngữ cảnh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói (Point and say), thay thế từ; quan sát, sửa lỗi.","hs":"- HS luyện hỏi–đáp theo cặp; đổi vai."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật về nơi đến, hoạt động hè.","hs":"- HS vận dụng mẫu câu giao tiếp; xung phong trình bày."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":34,"tiet":1,"bai":"Unit 20 — Lesson 2 (Pronunciation & Song) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ngữ âm/Phát âm: nhận biết và phát âm đúng trọng âm/âm trọng tâm (Âm /h/ trong holiday, home; chant về kì nghỉ hè.).\n- Nghe–Nói: hát/đọc chant, luyện nói củng cố mẫu câu về nơi đến, hoạt động hè.\n- Đọc–Viết: đọc và viết câu vận dụng ngữ liệu.\nNgữ liệu trọng tâm: stay at home, travel to; with my family; mẫu câu: Where are you going to go? – I'm going to travel to Da Nang.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phát âm đúng Âm /h/ trong holiday, home.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Pronunciation & Song” (Unit 20) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 20.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Pronunciation (Ngữ âm – Phát âm)","gv":"- GV giới thiệu và luyện âm/trọng âm trọng tâm: Âm /h/ trong holiday, home; chant về kì nghỉ hè..\n- Đọc mẫu, cho HS nghe và nhắc lại (Listen and repeat).","hs":"- HS nghe, nhận biết âm; luyện phát âm đúng."},{"ten":"3. Practice – Let's chant/sing (Luyện tập)","gv":"- GV cho HS đọc chant/hát bài hát của Unit; kết hợp luyện nói củng cố mẫu câu \"Where are you going to go? – I'm going to travel to Da Nang.\".","hs":"- HS đọc chant/hát theo nhịp; luyện nói theo cặp."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS viết và nói câu vận dụng về nơi đến, hoạt động hè.","hs":"- HS viết câu, trình bày trước lớp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở phần Pronunciation của Unit 20 “Our summer holidays”: chiếu từ có gạch chân phần cần luyện (Âm /h/ trong holiday, home; chant về kì nghỉ hè), bật audio đọc mẫu rồi cho nghe lại từng từ ở tốc độ chậm; HS tự nêu từ nào mình chưa nghe rõ để GV tua đúng chỗ đó, so cách đọc của mình với mẫu.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) Ở phần Let’s chant/Let’s sing, GV bật bài chant kèm lời chạy trên màn hình cho cả lớp hát nối theo, sau đó bật riêng phần nhạc nền để HS tự chant; nhóm nào chưa vào nhịp thì nghe lại đúng câu đó ở tốc độ chậm rồi ghép lại — nghe chậm và tua đúng câu là việc chỉ làm được với bản ghi âm.\n⚠ (Miền 4: An toàn) Loa mở vừa đủ nghe, không mở quá to khi cả lớp hát theo; HS đeo tai nghe thì để âm lượng nhỏ và bỏ ra ngay khi thấy ù tai. Bài chant và bài hát mở từ nguồn của SGK; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không mở clip có nội dung không phù hợp lứa tuổi. Không quay phim bạn đang hát rồi đăng lên nhóm chat.","hs":"- HS phát âm đúng Âm /h/ trong holiday, home; chant về kì nghỉ hè của Unit 20 “Our summer holidays” sau khi nghe lại phần audio mẫu ở tốc độ chậm.\n- HS chant và hát được đúng nhịp theo nhạc nền, tự nhận ra câu nào mình còn lệch nhịp để nghe lại."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":34,"tiet":2,"bai":"Unit 20 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe hiểu đoạn hội thoại/thông tin về chủ đề, làm bài tập nghe.\n- Đọc: đọc hiểu đoạn văn ngắn về kĩ năng: nghe–đọc–viết về kì nghỉ hè, trả lời câu hỏi.\n- Nói: trao đổi thông tin đã nghe/đọc theo cặp.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 20; mẫu câu: đọc/viết về kế hoạch nghỉ hè của em.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và làm đúng bài Listen and tick của Unit 20 “Our summer holidays”, chỉ ra được từ khoá quyết định đáp án.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 20 (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 20.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV cho HS nghe đoạn hội thoại/thông tin về kĩ năng: nghe–đọc–viết về kì nghỉ hè; làm bài tập nghe (Listen and tick/circle/complete); chữa bài.","hs":"- HS nghe, làm bài, đối chiếu đáp án; nghe lại để kiểm tra."},{"ten":"3. Reading (Đọc)","gv":"- GV cho HS đọc đoạn văn ngắn về chủ đề; hướng dẫn trả lời câu hỏi (Read and answer/tick).","hs":"- HS đọc, tìm thông tin, trả lời câu hỏi; đọc lại to–rõ."},{"ten":"4. Post – Speaking (Củng cố)","gv":"- GV cho HS trao đổi theo cặp thông tin vừa nghe/đọc.","hs":"- HS hỏi–đáp, chia sẻ thông tin với bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bài Listen and tick của Unit 20 “Our summer holidays”: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS ghi đáp án, lần 3 nghe lại để tự soát; HS nêu chính xác câu số mấy mình chưa nghe rõ để GV tua đúng đoạn đó và cùng chỉ ra từ khoá quyết định đáp án.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Ở phần Read and complete, HS tự tra từ chưa biết trong từ điển điện tử, đọc cả nghĩa lẫn ví dụ rồi đối chiếu với câu trong bài đọc về Our summer holidays để chọn nghĩa hợp ngữ cảnh; GV cho hai HS tra cùng một từ mà chọn nghĩa khác nhau trình bày lí do của mình.\n⚠ (Miền 4: An toàn) Chỉ mở trang từ điển GV chỉ định, không chuyển sang trang khác trong giờ đọc. Nghĩa lấy từ từ điển phải đối chiếu với câu trong bài rồi mới chép vào vở, không lấy ngay nghĩa đầu tiên máy đưa ra. Không chụp bài làm của bạn và không gửi đáp án cho nhau qua tin nhắn.","hs":"- HS nghe và làm đúng bài Listen and tick của Unit 20 “Our summer holidays”, chỉ ra được từ khoá quyết định đáp án.\n- HS chọn được nghĩa hợp với ngữ cảnh bài đọc về Our summer holidays và giải thích được vì sao chọn nghĩa đó."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":34,"tiet":3,"bai":"Unit 20 — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Viết: đọc/viết về kế hoạch nghỉ hè của em.\n- Nói: trình bày sản phẩm/dự án nhỏ trước lớp.\n- Nghe–Đọc: củng cố kĩ năng qua trò chơi ôn tập.\nNgữ liệu trọng tâm: ôn ngữ liệu Unit 20; mẫu câu: đọc/viết về kế hoạch nghỉ hè của em.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện phát âm, ghi nhớ từ mới, hoàn thành nhiệm vụ.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng ngữ liệu vào tình huống giao tiếp mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói–đọc–viết, hoàn thành nhiệm vụ học tập.\n- Nhân ái, tôn trọng: lịch sự khi giao tiếp, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết và trình bày được một trang giới thiệu về Our summer holidays bằng câu của chính mình, có hình do mình vẽ hoặc chụp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 20) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 20.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết theo mẫu: đọc/viết về kế hoạch nghỉ hè của em.\n- Gợi ý dàn ý, cung cấp từ nối; quan sát, hỗ trợ.","hs":"- HS viết đoạn/câu theo mẫu; đọc lại, sửa lỗi cùng bạn."},{"ten":"3. Project/Production (Dự án – Vận dụng)","gv":"- GV tổ chức dự án nhỏ (làm poster/giới thiệu về chủ đề Unit); cho HS trình bày.","hs":"- HS làm sản phẩm nhóm, trình bày trước lớp; nhận xét lẫn nhau."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV cho HS chơi trò chơi ôn tập cả Unit; tổng kết ngữ liệu trọng tâm.","hs":"- HS tham gia, tự đánh giá mức đạt được."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Ở phần Let’s write và Project của Unit 20 “Our summer holidays”, HS viết đoạn 4-5 câu của mình rồi gõ lại trên máy tính của lớp, chèn một hình do em tự vẽ hoặc tự chụp và trình bày thành một trang giới thiệu về Our summer holidays; HS dùng chức năng soát chính tả để tìm lỗi nhưng tự đọc lại và tự quyết định sửa chỗ nào.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ ý tiếng Việt của một HS vào công cụ dịch tự động và chiếu kết quả: máy trả về câu dùng cấu trúc chưa học, có chỗ lệch nghĩa; cả lớp đối chiếu với mẫu câu của Unit 20 “Our summer holidays” rồi sửa lại. GV chốt về liêm chính học tập: nộp bài do công cụ dịch hay trợ lí trí tuệ nhân tạo viết hộ rồi nhận là của mình là không trung thực; công cụ dịch chỉ dùng để tra một từ chưa biết và phải kiểm tra lại nghĩa trong ngữ cảnh.\n⚠ (Miền 4: An toàn) Câu trong bài phải do chính HS đặt; nếu có tra từ bằng công cụ dịch thì ghi lại từ đã tra để GV biết. Hình chèn vào trang giới thiệu phải do HS tự vẽ, tự chụp hoặc là hình được phép dùng và có ghi nguồn; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài. Không ghi địa chỉ nhà, số điện thoại lên trang giới thiệu sẽ chiếu cho cả lớp xem.","hs":"- HS viết và trình bày được một trang giới thiệu về Our summer holidays bằng câu của chính mình, có hình do mình vẽ hoặc chụp.\n- HS nêu được vì sao nộp bài do công cụ dịch hoặc trợ lí trí tuệ nhân tạo viết hộ là không trung thực."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":34,"tiet":4,"bai":"Review 4 (Ôn tập – Nghe – Đọc)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá và củng cố ngữ liệu (từ vựng, mẫu câu) qua kĩ năng Nghe – Đọc của các Unit đã học.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề và sáng tạo.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực trong ôn tập và kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS làm được bài ôn tương tác của “Review 4 (Ôn tập – Nghe – Đọc)”, tự xác định ba phần còn yếu trong Unit 16–20 và chọn bài luyện tiếp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 16–20.\n- Nêu mục tiêu Review 4: củng cố kĩ năng Nghe và Đọc.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 16–20.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn tập theo kĩ năng","gv":"- GV tổ chức ôn Nghe – Đọc qua hệ thống bài tập (Listen/Read/Speak/Write) trong phần Review.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập theo cặp/nhóm, vận dụng ngữ liệu tổng hợp.","hs":"- HS thực hành, sửa lỗi cho nhau."},{"ten":"4. Fun time / Củng cố","gv":"- GV tổ chức trò chơi/hoạt động Fun time; tổng kết kiến thức trọng tâm.","hs":"- HS tham gia, hệ thống lại ngữ liệu đã ôn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) GV giao bộ bài tập tương tác có chấm tự động cho “Review 4 (Ôn tập – Nghe – Đọc)” với ngữ liệu Unit 16–20: nghe chọn đáp án, đọc đoạn rồi trả lời câu hỏi, sắp lại trật tự câu. HS tự làm, đọc kết quả từng câu, ghi ra ba phần mình sai nhiều nhất rồi chọn tiếp bài luyện đúng phần đó.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tự tra lại trong từ điển điện tử những từ của Unit 16–20 còn quên, đọc cả nghĩa lẫn ví dụ để chọn nghĩa hợp ngữ cảnh, nghe phát âm rồi sắp xếp bổ sung vào sổ tay từ vựng theo nhóm chủ đề để dễ ôn.\n⚠ (Miền 4: An toàn) Tự làm hết bài rồi mới xem đáp án; kết quả máy chấm là để biết mình hổng chỗ nào, không phải để so điểm với bạn. Chỉ mở đúng đường dẫn GV gửi, không mở sang mạng xã hội hay trò chơi trong giờ ôn. Không đăng nhập bằng tài khoản của bạn và không gõ họ tên đầy đủ, ngày sinh khi phần mềm hỏi.","hs":"- HS làm được bài ôn tương tác của “Review 4 (Ôn tập – Nghe – Đọc)”, tự xác định ba phần còn yếu trong Unit 16–20 và chọn bài luyện tiếp.\n- HS tra và sắp xếp bổ sung được từ còn quên vào sổ tay từ vựng theo nhóm chủ đề."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":35,"tiet":1,"bai":"Review 4 (Ôn tập – Nói – Viết)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá và củng cố ngữ liệu (từ vựng, mẫu câu) qua kĩ năng Nói – Viết của các Unit đã học.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề và sáng tạo.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực trong ôn tập và kiểm tra – đánh giá.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 16–20.\n- Nêu mục tiêu Review 4: củng cố kĩ năng Nói và Viết.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 16–20.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn tập theo kĩ năng","gv":"- GV tổ chức ôn Nói – Viết qua hệ thống bài tập (Listen/Read/Speak/Write) trong phần Review.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập theo cặp/nhóm, vận dụng ngữ liệu tổng hợp.","hs":"- HS thực hành, sửa lỗi cho nhau."},{"ten":"4. Fun time / Củng cố","gv":"- GV tổ chức trò chơi/hoạt động Fun time; tổng kết kiến thức trọng tâm.","hs":"- HS tham gia, hệ thống lại ngữ liệu đã ôn."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":35,"tiet":2,"bai":"Review 4 (Fun time & Củng cố)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá và củng cố ngữ liệu (từ vựng, mẫu câu) qua kĩ năng tổng hợp của các Unit đã học.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề và sáng tạo.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực trong ôn tập và kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS tham gia bộ câu hỏi tương tác ôn Unit 16–20 trong “Review 4 (Fun time & Củng cố)” và chỉ ra được nhóm từ mình còn quên nhiều nhất.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 16–20.\n- Nêu mục tiêu Review 4: củng cố trò chơi ngôn ngữ, hệ thống hoá từ vựng – mẫu câu.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 16–20.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn tập theo kĩ năng","gv":"- GV tổ chức ôn tổng hợp qua hệ thống bài tập (Listen/Read/Speak/Write) trong phần Review.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập theo cặp/nhóm, vận dụng ngữ liệu tổng hợp.","hs":"- HS thực hành, sửa lỗi cho nhau."},{"ten":"4. Fun time / Củng cố","gv":"- GV tổ chức trò chơi/hoạt động Fun time; tổng kết kiến thức trọng tâm.","hs":"- HS tham gia, hệ thống lại ngữ liệu đã ôn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) GV tổ chức phần Fun time của “Review 4 (Fun time & Củng cố)” bằng bộ câu hỏi tương tác chấm tự động cho ngữ liệu Unit 16–20: nghe đoán từ, ghép câu, đoán chữ; HS chơi theo nhóm, nhìn bảng điểm hiện ngay trên màn hình và tự chỉ ra nhóm từ nào cả nhóm còn quên nhiều nhất.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV gõ một câu ôn tập của Unit 16–20 vào công cụ dịch tự động rồi dịch ngược lại tiếng Việt, chiếu cả hai chiều cho HS thấy nghĩa đã lệch đi thế nào; HS giải thích vì sao không nên tin ngay câu máy dịch mà phải đối chiếu với mẫu câu đã học trong SGK.\n⚠ (Miền 4: An toàn) Chơi theo nhóm thì thắng thua vui vẻ, không chê bạn trả lời sai; bảng điểm là để biết nhóm mình cần ôn gì, không phải để xếp hạng bạn nào giỏi bạn nào kém. Chỉ mở đúng đường dẫn trò chơi GV gửi, không mở sang trang khác; phần mềm hỏi tên thì dùng tên nhóm, không gõ họ tên đầy đủ của HS.","hs":"- HS tham gia bộ câu hỏi tương tác ôn Unit 16–20 trong “Review 4 (Fun time & Củng cố)” và chỉ ra được nhóm từ mình còn quên nhiều nhất.\n- HS giải thích được vì sao phải đối chiếu câu do công cụ dịch đưa ra với mẫu câu trong SGK."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":35,"tiet":3,"bai":"Ôn tập cuối học kì II","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, hệ thống hoá ngữ liệu và bốn kĩ năng, chuẩn bị kiểm tra định kì.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác.\n3. Phẩm chất:\n- Chăm chỉ, tự tin, trung thực.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS làm được bài ôn tương tác của “Ôn tập cuối học kì II”, tự xác định ba phần còn yếu trong Unit 11–20 và chọn bài luyện tiếp.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up","gv":"- GV cho HS chơi trò chơi/hỏi–đáp nhanh để huy động lại kiến thức đã học trong học kì.\n- Nêu mục tiêu tiết ôn tập, hệ thống các Unit trọng tâm chuẩn bị kiểm tra.","hs":"- HS tham gia, nhắc lại chủ đề – từ vựng; xác định nội dung cần ôn."},{"ten":"2. Ôn tập tổng hợp","gv":"- GV hệ thống từ vựng, mẫu câu, ngữ âm trọng tâm; luyện đề theo bốn kĩ năng.","hs":"- HS làm bài, chữa và tự đánh giá."},{"ten":"3. Luyện tập – Củng cố","gv":"- GV giải đáp thắc mắc, hướng dẫn cách làm từng dạng bài.","hs":"- HS luyện tập, ghi nhớ lưu ý."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) GV giao bộ bài tập tương tác có chấm tự động cho “Ôn tập cuối học kì II” với ngữ liệu Unit 11–20: nghe chọn đáp án, đọc đoạn rồi trả lời câu hỏi, sắp lại trật tự câu. HS tự làm, đọc kết quả từng câu, ghi ra ba phần mình sai nhiều nhất rồi chọn tiếp bài luyện đúng phần đó.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tự tra lại trong từ điển điện tử những từ của Unit 11–20 còn quên, đọc cả nghĩa lẫn ví dụ để chọn nghĩa hợp ngữ cảnh, nghe phát âm rồi sắp xếp bổ sung vào sổ tay từ vựng theo nhóm chủ đề để dễ ôn.\n⚠ (Miền 4: An toàn) Tự làm hết bài rồi mới xem đáp án; kết quả máy chấm là để biết mình hổng chỗ nào, không phải để so điểm với bạn. Chỉ mở đúng đường dẫn GV gửi, không mở sang mạng xã hội hay trò chơi trong giờ ôn. Không đăng nhập bằng tài khoản của bạn và không gõ họ tên đầy đủ, ngày sinh khi phần mềm hỏi.","hs":"- HS làm được bài ôn tương tác của “Ôn tập cuối học kì II”, tự xác định ba phần còn yếu trong Unit 11–20 và chọn bài luyện tiếp.\n- HS tra và sắp xếp bổ sung được từ còn quên vào sổ tay từ vựng theo nhóm chủ đề."}]},
{"lop":5,"mon":"Tiếng Anh","tuan":35,"tiet":4,"bai":"Kiểm tra định kì cuối học kì II","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Đánh giá kết quả cuối học kì II qua bốn kĩ năng Nghe – Đọc – Nói – Viết theo ma trận đề phù hợp chuẩn đầu ra Tiếng Anh 5.\n2. Năng lực chung:\n- Tự chủ và tự học; Giải quyết vấn đề.\n3. Phẩm chất:\n- Trung thực, tự giác, nghiêm túc trong kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 6.1 CB2 (Hiểu biết về trí tuệ nhân tạo): HS thực hiện đúng quy định không dùng thiết bị số trong giờ kiểm tra, làm bài bằng năng lực của chính mình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 5 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 5 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Ổn định – Phổ biến","gv":"- GV ổn định lớp, tạo tâm lí thoải mái, tự tin trước khi làm bài.\n- Nhắc hình thức, thời gian và quy tắc làm bài kiểm tra; phát đề.","hs":"- HS chuẩn bị đồ dùng, giữ trật tự, lắng nghe hướng dẫn làm bài."},{"ten":"2. Làm bài / Thực hiện","gv":"- GV phát đề/tổ chức kiểm tra bốn kĩ năng; coi kiểm tra nghiêm túc.","hs":"- HS làm bài độc lập, trung thực."},{"ten":"3. Thu bài – Nhận xét","gv":"- GV thu bài, nhận xét chung tinh thần, thái độ làm bài.","hs":"- HS nộp bài, rút kinh nghiệm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) Tiết kiểm tra là dịp dạy chính về liêm chính học tập: GV nêu rõ công cụ dịch tự động và trợ lí trí tuệ nhân tạo có thể làm hộ cả bài nghe, đọc, viết, nhưng bài kiểm tra là để đo năng lực thật của chính HS; vì vậy trong giờ kiểm tra tuyệt đối không dùng thiết bị số.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) Sau khi trả bài, GV hướng dẫn HS dùng từ điển Anh – Việt điện tử tra lại đúng những từ mình làm sai, nghe phát âm chuẩn và ghi vào sổ tay từ vựng của riêng mình.\n⚠ (Miền 4: An toàn) Không mang và không sử dụng thiết bị số trong giờ kiểm tra; không chụp đề bài gửi lên nhóm chat hay ứng dụng nào; không nhờ người khác làm hộ qua mạng.","hs":"- HS thực hiện đúng quy định không dùng thiết bị số trong giờ kiểm tra, làm bài bằng năng lực của chính mình.\n- HS nêu được vì sao nhờ công cụ dịch hay trợ lí AI làm hộ bài kiểm tra là không trung thực; sau khi trả bài mới dùng từ điển điện tử để học lại từ chưa biết."}]}
];
